//! Instruction selection: IR → m68k instructions (CLAUDE.md 4.4).
//!
//! Three steps per routine:
//!
//! 1. **Body.**  Pattern-directed, one IR node at a time, over virtual
//!    registers (`regs.rs`): every value a pattern computes gets a new
//!    one.  A pattern that loads A5 records it in the selector's
//!    `clobbered` set.
//! 2. **Registers.**  [`crate::regs::allocate`] computes the live ranges
//!    of the body and gives each value the lowest register of its class
//!    free over its whole range, a callee-saved one if it lives across a
//!    call (codegen-patterns 12.4, R1-R3), and rewrites the body.
//!    [`crate::sched::schedule`] then orders the instructions inside
//!    each basic block (codegen-patterns 12.4 R9-R12; R11 with a window
//!    of 3 by default).
//! 3. **Frame.**  The callee-saved registers the body wrote decide the
//!    save set; [`crate::frame::Frame`] then gives the prologue (`link.w`,
//!    the save) and the epilogue (the restore from the frame, `unlk`,
//!    `rts`) around the body.
//!
//! Each pattern cites the image address(es) it reproduces.  Patterns the
//! image has not shown are rejected, not guessed.

use dpc_ir::{
    Access, Addr, Arg, BinOp, BitField, Call, Callee, CaseArm, Cond as IrCond, Expr, ForLoop,
    Function, LinkArg, Rel, ResultClass, ResultSpec, Scalar, SetOp, Sign, StaticLink, Stmt,
    StmtKind, UnOp, Width,
};
use dpc_syntax::{Diagnostic, Span};
use std::borrow::Cow;
use std::collections::BTreeSet;

use crate::emit::DATA_BASE_LABEL;
use crate::frame::{frame_for, FP, SP};
use crate::insn::{AluOp, BitOp, Cond, Ea, Insn, Reg, RegSet, ShiftCount, ShiftOp, Size, UnaryOp};
use crate::regs::{allocate_apart, call_results_first, RegClass, VRegs, DATA_BASE};
use crate::sched::Schedule;
use crate::Cpu;

mod merge;
mod with_bias;

/// The register a nested routine's static link is passed in
/// (codegen-patterns 6: 0xE13928 `movea.l A6,A1; bsr.w 0xE1359C`).
const STATIC_LINK_A: u8 = 1;

/// A5, the data base register, as an address register number.
const DATA_BASE_A: u8 = 5;

type Res<T> = Result<T, Diagnostic>;

fn unsupported(span: Span, what: impl std::fmt::Display) -> Diagnostic {
    Diagnostic::error(span, format!("{what} not supported yet"))
}

/// The refusal `unsupported(span, what)` of a shape dpc has a correct
/// code path for, refused only because the image's exact form (register
/// choice, instruction order, hold or reload, which of two seen forms) is
/// not settled: an error under `dpc --strict`, else a best-effort warning
/// and `Ok`, and the caller goes on with its path
/// ([`dpc_syntax::diag::best_effort`]; bead domain-pascal-5kgg).
fn best_effort(span: Span, what: impl std::fmt::Display) -> Res<()> {
    dpc_syntax::diag::best_effort(unsupported(span, what))
}

/// The instructions over which the value register `v`, defined at `k`
/// and last read at `last`, is live, as a range `lo..=hi` of `out`: the
/// straight run from `k` to `last`, widened by loops (a branch back to a
/// label at or before it).  A loop the value enters, defined before it
/// and read in it, holds it to its back branch; one in which it is read
/// before its definition (round the loop) holds it from its head.
fn live_range(out: &[Insn], v: Reg, k: usize, last: usize) -> (usize, usize) {
    let at = |l: u32| {
        out.iter()
            .position(|i| matches!(i, Insn::Label(m) if *m == l))
    };
    let loops: Vec<(usize, usize)> = out
        .iter()
        .enumerate()
        .flat_map(|(b, i)| {
            let targets: Vec<u32> = match i {
                Insn::Branch { label, .. } | Insn::Dbf { label, .. } => vec![*label],
                Insn::TableJump { targets, .. } => targets.clone(),
                _ => Vec::new(),
            };
            targets
                .into_iter()
                .filter_map(at)
                .filter(move |&t| t <= b)
                .map(move |t| (t, b))
        })
        .collect();
    let reads = |from: usize, to: usize| {
        out[from..to]
            .iter()
            .any(|i| crate::regs::access(i).uses.contains(&v))
    };
    let (mut lo, mut hi) = (k, last.max(k));
    loop {
        let (l0, h0) = (lo, hi);
        for &(t, b) in &loops {
            if t < lo && lo <= b && reads(t, lo) {
                lo = t;
                hi = hi.max(b);
            }
            if lo < t && t <= hi && hi < b {
                hi = b;
            }
        }
        if (lo, hi) == (l0, h0) {
            return (lo, hi);
        }
    }
}

/// The refusal of a `lea (0,An,Dx),Am` from the base of another unit's
/// array that an earlier statement loaded ([`Selector::held_other_base`]).
const KEPT_BASE_LEA: &str = "an element of another unit's array that an earlier statement since \
     the last call reached too, at a displacement beyond a byte or as an address (`lea \
     (0,An,Dx),Am` from the kept base: 8 sites, its register not surveyed; codegen-patterns \
     5.2, \"Base kept across statements\"; bead domain-pascal-lnzy) is";

/// Whether `ea` is a memory operand `lea` takes (a control addressing
/// mode, MC68000 PRM 2.2): a best-effort block address ([`Selector::
/// block_address`]; bead domain-pascal-5kgg).
fn is_memory_ea(ea: &Ea) -> bool {
    matches!(
        ea,
        Ea::Ind(_) | Ea::Disp(..) | Ea::Idx(..) | Ea::Idx2(..) | Ea::AbsL(..) | Ea::AbsW(_)
    )
}

/// The refusal of a second call while a function's (or M$ARITH's) result
/// may still be needed in D0 or A0 ([`Selector::call_value`],
/// [`Selector::marith`]): the statement is selected again in
/// [`CallMode::save`].
const TWO_CALLS: &str = "two function calls in one statement are";

/// The best-effort form of [`CallMode::save`] ([`Selector::save_result`]).
const SAVED_RESULT: &str = "a call whose result is still needed at a later call of its statement \
     (the result copied out of D0 or A0 into a register of its own; PACCT_$CLOCK_TO_COMP \
     0xE5AA6C keeps one in a frame temporary, the right operand first: the rule not known, \
     codegen-patterns 1.1, bead domain-pascal-ej8m) is";

/// The best-effort form of an M$ARITH call among another call's arguments
/// ([`Selector::marith`]).
const MARITH_IN_ARGS: &str = "an M$ARITH call among another call's arguments (popped at once, \
     as a function call there: not catalogued, codegen-patterns 1.1) is";

/// How the calls of one statement are selected when the first selection
/// refused them ([`select_body_in_unit`]; bead domain-pascal-ej8m).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct CallMode {
    /// Every call of the statement is popped right after it, as the
    /// image pops every call that a push, a call or a conditional branch
    /// follows (codegen-patterns 1.1); best effort for the statement's
    /// last call, which the image may leave unpopped.
    pop: bool,
    /// Each call's result is copied out of D0 / A0 into a register of its
    /// own right after the call (and its pop), so that a later call of
    /// the statement does not overwrite it; the allocator gives one live
    /// across a call a callee-saved register (codegen-patterns 12.4 R3).
    /// Best effort (not byte-identical): PACCT_$CLOCK_TO_COMP
    /// 0xE5AA3A..0xE5AA86 evaluates the right operand of `+` first and
    /// keeps its M$ARITH result in a frame temporary (`move.l
    /// D0,(-0x18,A6)` ... `add.l (-0x18,A6),D0`), which `dpc` does not
    /// model (one site; the rule for the order is not known).
    save: bool,
}

/// A constant as the immediate of a `w`-sized instruction: a byte as
/// 0..=255 (see [`Ea::Imm`]), a word or longword as the signed number.
fn imm(value: i64, w: Width) -> i64 {
    match w {
        Width::Byte => value & 0xff,
        Width::Word => value as i16 as i64,
        Width::Long => value as i32 as i64,
    }
}

/// The condition code under which `a op b` holds after `cmp b,a` (or
/// `cmpi #b,a`): signed or unsigned (MC68000 PRM, Table 3-19).
fn rel_cond(op: Rel, signed: bool) -> Cond {
    match (op, signed) {
        (Rel::Eq, _) => Cond::Eq,
        (Rel::Ne, _) => Cond::Ne,
        (Rel::Lt, true) => Cond::Lt,
        (Rel::Le, true) => Cond::Le,
        (Rel::Gt, true) => Cond::Gt,
        (Rel::Ge, true) => Cond::Ge,
        (Rel::Lt, false) => Cond::Cs,
        (Rel::Le, false) => Cond::Ls,
        (Rel::Gt, false) => Cond::Hi,
        (Rel::Ge, false) => Cond::Cc,
    }
}

/// The warning of an unsigned ordering comparison with 0
/// ([`unsigned_zero_rel`]).
const UNSIGNED_ZERO: &str = "an unsigned ordering comparison with 0 (no form catalogued, \
     codegen-patterns 7.1) is";

/// An unsigned `x op 0` for an ordering `op`: `x <= 0` is `x = 0` and `x >
/// 0` is `x <> 0`; `x < 0` is never true and `x >= 0` always, kept as
/// `Lt`/`Ge`, which the callers test with `tst` (C clear) and
/// `bcs`/`bcc`.  `None` for a signed `x` or `=`/`<>`.  Only byte types
/// that use the top bit (`0..255`) reach here: `dpc-ir` `compare` makes
/// an unsigned type whose values fit the signed range, and any unsigned
/// word, a sign test, as the image does (BAT_$FREE 0xE3B5B0,
/// PKT_$BLD_INTERNET_HDR 0xE122D6; bead domain-pascal-wkm5).  Best effort
/// (not byte-identical; bead domain-pascal-uaq7): no compiled form of a
/// top-bit byte against 0 is catalogued.
fn unsigned_zero_rel(op: Rel, signed: bool) -> Option<Rel> {
    match (op, signed) {
        (_, true) | (Rel::Eq | Rel::Ne, _) => None,
        (Rel::Le, false) => Some(Rel::Eq),
        (Rel::Gt, false) => Some(Rel::Ne),
        (o, false) => Some(o),
    }
}

/// The relation `r` with its operands exchanged: `a r b` = `b (swap_rel
/// r) a`.
fn swap_rel(r: Rel) -> Rel {
    match r {
        Rel::Eq | Rel::Ne => r,
        Rel::Lt => Rel::Gt,
        Rel::Gt => Rel::Lt,
        Rel::Le => Rel::Ge,
        Rel::Ge => Rel::Le,
    }
}

/// Whether a multiplication by the constant `c` is done with shifts and
/// adds ([`Selector::mul_const`]): `c` = 2^s × m with m = 1 or 2^k ± 1
/// (2^k - 1 for k >= 3), `c` in 1..=0xffff.
fn by_shifts(c: i64) -> bool {
    if !(1..=0xffff).contains(&c) {
        return false;
    }
    let m = (c >> c.trailing_zeros()) as u32;
    m == 1 || (m - 1).is_power_of_two() || (m > 3 && (m + 1).is_power_of_two())
}

/// Whether a multiplication by the constant `c` that is not done with
/// shifts and adds ([`by_shifts`]) is one `mul<s>.w` (codegen-patterns 8,
/// "Multiplication by a constant"; `tools/arithsurvey.py scale`): `c` in
/// 1..=0xffff with an odd part of four bits or more (23: ×46, ×92; 75:
/// ×150; 51, 57, 61, 125, 141, 153, 203, 311, 655, 1083, 12345), or one of the
/// odd parts of three bits seen with a multiply: 11 (×44, TPAD_$SET_UNIT_MODE
/// 0xE69826), 25 (×100, VTOC_$MOUNT 0xE38614), 21 (×336, 0xE395AA; ×84,
/// HINT_$GET_HINTS 0xE4999A), 67 (×268, 0xE1D7A2), 145 (×580, 0xE2FB08).  Odd part 13 is done bit by bit
/// (×26, NETLOG_$LOG_IT 0xE71BBA, the one such site) and no other odd part
/// of three bits is seen: refused (bead domain-pascal-irb4).
fn by_mul_insn(c: i64) -> bool {
    if !(1..=0xffff).contains(&c) || by_shifts(c) {
        return false;
    }
    let m = (c >> c.trailing_zeros()) as u32;
    m.count_ones() >= 4 || [11, 21, 25, 67, 145].contains(&m)
}

/// Whether a product of `x` by a constant of 1..=127 done with a multiply
/// puts the constant in the register (`moveq #c,Dn; mul<s>.w x,Dn`,
/// [`Selector::mul_const_first`]): `x` a variable.  For a computed value
/// see [`in_place`].
fn const_first(x: &Expr) -> bool {
    matches!(x, Expr::Load { .. })
}

/// Whether a computed `x` times a constant of 1..=127 done with a
/// multiply is multiplied in place, `mul<s>.w #c`: a zero-extended byte
/// (RIP_$BROADCAST 0xE872F8 `clr.w D5; move.b (14,A2),D5; mulu.w #92,D5`,
/// the one in-place site).  Other computed values are refused
/// ([`computed_factor`]): the two others, masks, have the constant first
/// (HINT_$GET_HINTS 0xE4998E..0xE4999A `moveq #63,D3; moveq #84,D5; and.w
/// D0,D3; movea.l #sym,A1; muls.w D3,D5`; 0xE49A5C..0xE49A68).
fn in_place(x: &Expr) -> bool {
    matches!(x, Expr::Convert { value, .. }
        if value.ty().width == Width::Byte && !value.ty().is_signed()
            && matches!(**value, Expr::Load { .. }))
}

/// The refusal of a computed value other than a zero-extended byte times
/// a constant `c` of 1..=127 done with a multiply ([`in_place`]).
fn computed_factor(span: Span, c: i64) -> Diagnostic {
    unsupported(
        span,
        format!(
            "a multiplication by {c} of a computed value (`mul<s>.w #{c}` in place for a \
             zero-extended byte, RIP_$BROADCAST 0xE872F8; the constant first for a mask, \
             HINT_$GET_HINTS 0xE4998E; not settled, codegen-patterns 8; bead \
             domain-pascal-q322) is"
        ),
    )
}

/// The refusal of a multiplication by `c` whose odd part has three bits
/// and is not one seen with a multiply ([`by_mul_insn`]).
fn three_bit_odd_part(span: Span, c: i64) -> Diagnostic {
    unsupported(
        span,
        format!(
            "a multiplication by {c} (shifts and adds or `mul<s>.w`: odd parts of three bits \
             other than 11, 21, 25, 67 and 145 not settled, ×26 bit by bit at 0xE71BBA; bead \
             domain-pascal-irb4) is"
        ),
    )
}

fn size_of(w: Width) -> Size {
    match w {
        Width::Byte => Size::B,
        Width::Word => Size::W,
        Width::Long => Size::L,
    }
}

/// The memory operand `ea` moved `k` bytes up, when its mode allows it
/// (a 16-bit displacement, an 8-bit one with an index, an absolute
/// address); `None` otherwise.  Used to read the low bytes of a
/// big-endian object ([`Selector::convert`]).
fn displace(ea: &Ea, k: i32) -> Option<Ea> {
    Some(match ea {
        Ea::Ind(a) => Ea::Disp(k, *a),
        Ea::Disp(d, a) if i16::try_from(d + k).is_ok() => Ea::Disp(d + k, *a),
        Ea::Idx(d, a, x, l) if i8::try_from(d + k).is_ok() => Ea::Idx(d + k, *a, *x, *l),
        Ea::Idx2(d, a, x, l, s) if i16::try_from(d + k).is_ok() => Ea::Idx2(d + k, *a, *x, *l, *s),
        Ea::AbsL(s, o) => Ea::AbsL(s.clone(), o + k),
        Ea::AbsW(v) if i16::try_from(v + k).is_ok() => Ea::AbsW(v + k),
        _ => return None,
    })
}

/// Whether `value` narrowed to `ty` is read in place, its low bytes at
/// the higher address ([`displace`], [`Selector::convert`]): a load of a
/// non-volatile object one step wider (a longword as a word, a word as a
/// byte), not an element with a computed index.  A volatile object is
/// read at its own size (ref 3.15.1-3.15.3).  The narrowings an
/// assignment reads in place whatever the address (an element at a
/// computed index, a longword into a byte) come marked `in_place`
/// ([`Selector::narrow_in_place`], beads domain-pascal-d59a,
/// domain-pascal-dkik); unmarked, a computed-index element and a
/// longword come only from `chr`, which reads them whole as before
/// (`chr` of a field: TERM_$CONTROL 0xE66B64 `move.w (A0),D0; move.b
/// D0,(-0x36,A6)`, bead domain-pascal-4tu1).
fn narrows_in_place(value: &Expr, ty: Scalar) -> bool {
    value.ty().bytes() == 2 * ty.bytes()
        && matches!(
            value,
            Expr::Load {
                addr: Addr::Frame(_)
                    | Addr::Enclosing(_)
                    | Addr::Static(_)
                    | Addr::Symbol { .. }
                    | Addr::OtherStatic { .. }
                    | Addr::Indirect { .. },
                ..
            }
        )
}

/// Select the instructions of one routine, prologue to `rts`.
///
/// An empty procedure is a bare `rts`, without `link` (codegen-patterns
/// 2): TIME_$Q_INIT 0xE16C5C, IIC_$INIT 0xE70A54, SMD_$PUTC 0xE1D89C, and
/// MT_$RELEASE 0xE70A4C with its three by-address parameters (the image
/// has no `link; unlk; rts` at all).  One with locals is refused: no such
/// frame is seen, and whether it would be kept is not known.
///
/// The routine is selected as if its unit had no overlay sections (no
/// array of one is reached from 60000 bytes in, [`Selector::symbol_bias`]
/// gives 0): a unit's routines are selected by [`select_in_unit`]
/// (`emit.rs`).
pub fn select(f: &Function) -> Result<Vec<Insn>, Diagnostic> {
    select_with(f, Schedule::default())
}

/// [`select`] with the body scheduled under `sched` (`sched.rs`); no
/// overlay sections, as [`select`].
pub fn select_with(f: &Function, sched: Schedule) -> Result<Vec<Insn>, Diagnostic> {
    select_in_unit(f, sched, &[], false, Cpu::M68010)
}

/// The overlay sections of a unit (`dpc_ir::Module::overlays`): each
/// section's symbol and its size in the unit, for the base its arrays are
/// reached from ([`Selector::symbol_bias`]).
pub type Overlays = [(String, u32)];

/// [`select_with`] for a routine of a unit with overlay sections
/// `overlays`.
///
/// `merge`: the unit merges pairs of word constants stored to adjacent
/// words (`dpc --merge-constant-stores`; [`merge`], codegen-patterns 13,
/// "Store merging").
///
/// `cpu`: the processor (`-cpu`; [`Cpu`]): MC68020 code folds scaled
/// indices into operands, reads and writes bit fields with `bfextu` and
/// `bfins`, and multiplies and divides longwords inline (codegen-patterns
/// 14).
pub fn select_in_unit(
    f: &Function,
    sched: Schedule,
    overlays: &Overlays,
    merge: bool,
    cpu: Cpu,
) -> Result<Vec<Insn>, Diagnostic> {
    // For the driver's internal-error backstop (`diag::set_context`).
    let outer = dpc_syntax::diag::set_context(Some(f.span));
    let insns = select_in_context(f, sched, overlays, merge, cpu);
    dpc_syntax::diag::set_context(outer);
    insns
}

fn select_in_context(
    f: &Function,
    sched: Schedule,
    overlays: &Overlays,
    merge: bool,
    cpu: Cpu,
) -> Result<Vec<Insn>, Diagnostic> {
    let f = merge::adjacent_stores(f, merge)?;
    // MC68020: `with` temporaries of elements far from their symbol
    // (bead domain-pascal-2ys5; the module doc of `with_bias`).
    let f = if cpu.is_68020() {
        match with_bias::far_with_temps(&f) {
            Cow::Borrowed(_) => f,
            Cow::Owned(g) => Cow::Owned(g),
        }
    } else {
        f
    };
    let f: &Function = &f;
    if f.is_empty_procedure() {
        if let Some(pc) = f.param_copies.first() {
            // A bare `rts` has no frame for the copy; whether the original
            // copied an unused parameter is not visible (codegen-patterns
            // 1.2, 2).
            best_effort(
                pc.span,
                "an empty procedure with a value parameter passed by address (a bare `rts` \
                 in the image, so not copied; codegen-patterns 1.2, 2) is",
            )?;
        }
        if f.frame_size > 0 {
            best_effort(
                f.span,
                "an empty procedure with locals (a bare `rts` or a frame: not seen, \
                 codegen-patterns 2) is",
            )?;
        }
        return Ok(vec![Insn::Rts]);
    }
    let body = select_body_in_unit(f, sched, overlays, cpu)?;
    wrap(f, body)
}

/// Phase 2: the frame of `f` around `body`.
///
/// A body whose end nothing reaches (its last instruction a `bra` back
/// into it, no branch to the labels after that: a loop with no test and
/// no way out) has no epilogue: the image's 6 compiled routines with no
/// reachable `unlk`/`rts` all end in such a `bra`, followed by the next
/// routine or the routine's cells (DXM_$HELPER_COMMON 0xE1721C `bra.s
/// 0xE171FC`, then DXM_$HELPER_WIRED at 0xE1721E; PKT_$PING_SERVER
/// 0xE12D2E, PMAP_$PURIFIER_L 0xE14166, PMAP_$PURIFIER_R 0xE143AE,
/// PROC2_$DELETE 0xE743CC, the module-local 0xE76048 at 0xE76286;
/// codegen-patterns 7.2).  The prologue still saves the registers the body
/// writes (0xE171E8 `movem.l D2/A2-A4,-(SP)`).
pub fn wrap(f: &Function, body: Body) -> Result<Vec<Insn>, Diagnostic> {
    // Spill slots below the locals' rounded `link` area ([`crate::spill`]).
    let raw = if body.spill > 0 {
        crate::M68k::link_size(f.frame_size) + body.spill
    } else {
        f.frame_size
    };
    let frame = frame_for(raw, body.saves, f.span)?;
    let mut out = frame.prologue();
    let reached = end_reached(&body.insns);
    out.extend(body.insns);
    if reached {
        out.extend(frame.epilogue());
    }
    Ok(out)
}

/// Whether the end of `body` (where the epilogue goes) is reached: by
/// falling off its last instruction, or by a branch to a label after it.
fn end_reached(body: &[Insn]) -> bool {
    let Some(last) = body
        .iter()
        .rposition(|i| !matches!(i, Insn::Label(_) | Insn::Align4))
    else {
        return true;
    };
    if !matches!(body[last], Insn::Branch { cond: Cond::T, .. }) {
        return true;
    }
    let tail: Vec<u32> = body[last + 1..]
        .iter()
        .filter_map(|i| match i {
            Insn::Label(l) => Some(*l),
            _ => None,
        })
        .collect();
    body.iter().any(|i| match i {
        Insn::Branch { label, .. } | Insn::Dbf { label, .. } => tail.contains(label),
        Insn::TableEntry { target, .. } => tail.contains(target),
        _ => false,
    })
}

/// Phase 1's result: the body's instructions and the callee-saved
/// registers they write.
#[derive(Debug)]
pub struct Body {
    pub insns: Vec<Insn>,
    pub saves: RegSet,
    /// Frame bytes for spilled values below the locals ([`crate::spill`];
    /// 0 but where the body does not colour otherwise).
    pub spill: u32,
}

/// Phase 1: the body of `f`, without prologue and epilogue.
///
/// A body of one simple statement is selected in the statement's own
/// evaluation order (PROC1_$TST_LOCK 0xE148CA: the parameter is read where
/// the expression needs it, after the set's address).  A body of two or
/// more statements first loads the by-value parameters it reads into
/// registers ([`Selector::entry_loads`]; TIME_$Q_INIT_QUEUE
/// 0xE16C62..0xE16C6A).  Those loads, and the values the statements
/// compute, are ordinary values for the allocator (codegen-patterns 12.4
/// R1-R3): a parameter's register is free after its last use, a
/// statement's value takes the lowest register free over its live range,
/// and a value live across a call a callee-saved one (module-local
/// 0xE32B76, A2 and D2 around three calls).  Registers held longer than
/// the live range (12.4 R4) are modelled for a parameter the arguments of
/// a call read last ([`held_through_calls`]; PROC1_$SET_ASID 0xE148FE)
/// and for by-address slots read once, which avoid the registers of
/// earlier statements ([`fresh_slot_loads`]; IIC_$RECEIVE 0xE70ABA)
/// before a body's first branch or call, and after it only where the
/// lowest free register is clean on every path
/// ([`check_late_slot_loads`]); not to the end of a statement
/// (R4(a)), nor the scheduling of entry loads with other work (0xE758C4,
/// R9).
///
/// A function body of several statements is selected the same way, its
/// result variable held in a register up to the epilogue
/// ([`Selector::set_result_web`]; codegen-patterns 3, 12.4 R5).
///
/// A body that is one `if` or `repeat` statement is treated like a body of
/// several statements (NAME_CONVERT_ACL_STATUS 0xE58620: one `if ... else
/// if` chain, its by-address status loaded into A0 once, at the top), but
/// may not read by-value parameters: whether the original loaded them at
/// entry there is not known (codegen-patterns 12.2; the sites that load
/// them at entry have several statements).
///
/// Computed values used again later are reused from their register
/// (codegen-patterns 12.4 R7, [`Cse`]): the body is selected once to find
/// which computations a later one can reuse ([`Selector::cse_value`]),
/// then again holding exactly those.
///
/// As [`select`], with no overlay sections ([`Selector::symbol_bias`] 0).
pub fn select_body(f: &Function) -> Result<Body, Diagnostic> {
    select_body_scheduled(f, Schedule::default())
}

/// [`select_body`] with the body scheduled under `sched` after register
/// allocation (`sched.rs`, codegen-patterns 12.4 R9-R12); no overlay
/// sections, as [`select`].
pub fn select_body_scheduled(f: &Function, sched: Schedule) -> Result<Body, Diagnostic> {
    let f = merge::adjacent_stores(f, false)?;
    select_body_in_unit(&f, sched, &[], Cpu::M68010)
}

/// [`select_body_scheduled`] for a routine of a unit with overlay sections
/// `overlays` ([`select_in_unit`]).
fn select_body_in_unit(
    f: &Function,
    sched: Schedule,
    overlays: &Overlays,
    cpu: Cpu,
) -> Result<Body, Diagnostic> {
    // A statement whose calls are refused as they are first selected (a
    // second call while a result is still needed) is selected again with
    // its calls popped and their results saved ([`CallMode`]); the other
    // statements keep the form they had.
    let mut modes: Vec<(Span, CallMode)> = Vec::new();
    loop {
        let err = match select_body_moded(f, sched, overlays, &modes, cpu) {
            Err(e) => e,
            ok => return ok,
        };
        let Some(span) = err.span else {
            return Err(err);
        };
        let want = if err.message == format!("{TWO_CALLS} not supported yet") {
            CallMode {
                pop: true,
                save: true,
            }
        } else {
            return Err(err);
        };
        match modes.iter_mut().find(|(s, _)| *s == span) {
            Some((_, m)) if (m.pop || !want.pop) && (m.save || !want.save) => return Err(err),
            Some((_, m)) => {
                m.pop |= want.pop;
                m.save |= want.save;
            }
            None => modes.push((span, want)),
        }
    }
}

/// [`select_body_in_unit`] with the statements of `modes` selected in
/// their [`CallMode`].
fn select_body_moded(
    f: &Function,
    sched: Schedule,
    overlays: &Overlays,
    modes: &[(Span, CallMode)],
    cpu: Cpu,
) -> Result<Body, Diagnostic> {
    // A pointer result variable whose every assignment is last is kept
    // in its frame slot when one assignment reads memory, found for a
    // local only when selection sees it in the frame
    // ([`pointer_result_in_slot`]): the body is selected again so.
    let mut slot = SlotMode::Auto;
    let mut first = select_body_with(f, CsePlan::Probe, sched, &[], overlays, slot, modes, cpu)?;
    while let Selected::Reslot(mode) = first {
        slot = mode;
        first = select_body_with(f, CsePlan::Probe, sched, &[], overlays, slot, modes, cpu)?;
    }
    // A pointer local that no call follows is found by allocation; the
    // body is selected again with it held in A0 ([`Selector::a0_locals`]).
    let (body, hits, in_a0) = match first {
        Selected::Body(b, h) => (b, h, Vec::new()),
        Selected::InA0(in_a0) => {
            match select_body_with(f, CsePlan::Probe, sched, &in_a0, overlays, slot, modes, cpu)? {
                Selected::Body(b, h) => (b, h, in_a0),
                _ => unreachable!("an A0-held local is not found again"),
            }
        }
        Selected::Reslot(..) => unreachable!("selected again until settled"),
        Selected::Predefine(..) => unreachable!("selected again by select_body_with"),
    };
    if hits.is_empty() {
        return Ok(body);
    }
    let Selected::Body(body, again) = select_body_with(
        f,
        CsePlan::Hold(hits.clone()),
        sched,
        &in_a0,
        overlays,
        slot,
        modes,
        cpu,
    )?
    else {
        unreachable!("an A0-held local is not found again")
    };
    if again != hits {
        // The second selection must find the reuses the first one did:
        // the validity of a reuse depends only on labels, calls and
        // stores, which holding a value does not change.
        best_effort(
            f.span,
            "a body whose reusable computed values change when they are held (codegen-patterns \
             12.4 R7) is",
        )?;
    }
    Ok(body)
}

/// Where a function body assigns its result (codegen-patterns 3, "`nil`
/// results"; bead domain-pascal-bdi0).  An assignment is *last* when
/// nothing but the epilogue follows it in the text: it is the last
/// statement of the body (labels after it aside), or the last of a part
/// of an `if` or a `case` that is itself last.  One followed by `return`,
/// by other statements, or inside a loop is not.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ResultPositions {
    /// Every `f := e` of the body.
    all: usize,
    /// Those that are last.
    last: usize,
    /// The body's own last statement (labels aside) is `f := e`.
    top_last: bool,
}

/// [`ResultPositions`] of `body`.
fn result_positions(body: &[Stmt]) -> ResultPositions {
    fn walk(stmts: &[Stmt], last: bool, p: &mut ResultPositions) {
        let end = stmts
            .iter()
            .rposition(|st| !matches!(st.kind, StmtKind::Label(_)));
        for (i, st) in stmts.iter().enumerate() {
            let here = last && Some(i) == end;
            match &st.kind {
                StmtKind::SetResult(_) => {
                    p.all += 1;
                    p.last += usize::from(here);
                }
                StmtKind::If { then_, else_, .. } => {
                    walk(then_, here, p);
                    walk(else_, here, p);
                }
                StmtKind::Case {
                    arms, otherwise, ..
                } => {
                    for a in arms {
                        walk(&a.body, here, p);
                    }
                    if let Some(o) = otherwise {
                        walk(o, here, p);
                    }
                }
                k => {
                    for b in k.bodies() {
                        walk(b, false, p);
                    }
                }
            }
        }
    }
    let mut p = ResultPositions::default();
    walk(body, true, &mut p);
    p.top_last = body
        .iter()
        .rev()
        .find(|st| !matches!(st.kind, StmtKind::Label(_)))
        .is_some_and(|st| matches!(st.kind, StmtKind::SetResult(_)));
    p
}

/// The value assigned by a pointer result's `f := e`, as
/// [`pointer_result_in_slot`] tells them apart.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PointerValue {
    /// Read from memory: the unit's data, another unit's, through a
    /// pointer, an element, or a local whose address is taken
    /// ([`escaped_frame_objects`]).
    Memory,
    /// Another local: in memory or in a register, as selection holds it.
    Local,
    /// `nil`.
    Nil,
    /// Anything else: a parameter, a pointer function's result, a
    /// computed value.
    Other,
}

/// [`PointerValue`] of `e`; `escaped` as [`escaped_frame_objects`].
fn pointer_value(e: &Expr, escaped: &[i32]) -> PointerValue {
    match e {
        Expr::Const { value: 0, .. } => PointerValue::Nil,
        Expr::Load {
            addr: Addr::Frame(o),
            ..
        } if *o > 0 => PointerValue::Other,
        Expr::Load {
            addr: Addr::Frame(o),
            ..
        } if !escaped.contains(o) => PointerValue::Local,
        Expr::Load { .. } => PointerValue::Memory,
        _ => PointerValue::Other,
    }
}

/// Whether a pointer function body of several statements keeps its result
/// variable in its frame slot (codegen-patterns 3, "Pointer results",
/// "Every assignment last"; bead domain-pascal-yqsm): when every
/// assignment of the result is last ([`ResultPositions`]) and one of them
/// reads memory: [`PointerValue::Memory`], or a local that selection
/// finds in its frame slot (`slot`: selected again so,
/// [`Selector::slot_wanted`]).  Each assignment then stores into the slot
/// (`move.l <mem>,(-k,A6)`; `nil` as `clr.l (-k,A6)`), and the epilogue
/// starts with `movea.l (-k,A6),A0`, where a `return` branches to as well
/// (KBD_$GET_DESC 0xE1AA92/0xE1AA98, TTY_$I_GET_DESC 0xE667B0/0xE667B6,
/// SIO_$I_GET_DESC 0xE66808/0xE6680E, NET_$FIND_HANDLER
/// 0xE5A178/0xE5A180/0xE5A184, MST_$MAP_AREA 0xE43BF0/0xE43BF6 for a local
/// in the frame: 5 of the 5 such bodies; no `movea.l <memory>,A0` falls
/// into the epilogue of any pointer function, `tools/resultsurvey.py
/// pointer`).  A register-held local's value is moved from its register
/// instead, the variable held in A0 (AST_$ACTIVATE_ASTE_CANNED 0xE2F398
/// `movea.l A2,A0`, AST_$ALLOCATE_AOTE 0xE01F0C; the register-held
/// variable of [`Selector::set_pointer_result_web`]).
///
/// Gives the slot's offset when the body is selected with it (`None`
/// for the register-held variable) and whether the slot may still be
/// asked for (every assignment last, none a [`PointerValue::Other`]).
///
/// Best effort (not byte-identical): a body whose every assignment is
/// last that also assigns a pointer function's result (no site; the slot
/// as the only statement, MST_$MAP 0xE438BE `move.l A0,(-4,A6)`), a
/// parameter or a computed value beside memory (no site), or a
/// register-held local beside memory ([`SlotMode::Off`]; no site), keeps
/// the register-held variable dpc gave it before bead domain-pascal-yqsm
/// (those it refused then, a parameter or a computed value, it still
/// refuses there).
fn pointer_result_in_slot(
    f: &Function,
    escaped: &[i32],
    pos: ResultPositions,
    mode: SlotMode,
) -> Result<(Option<i32>, bool), Diagnostic> {
    let Some(res) = f.result else {
        return Ok((None, false));
    };
    if mode == SlotMode::Off
        || res.class != ResultClass::Address
        || pos.all == 0
        || pos.last != pos.all
    {
        return Ok((None, false));
    }
    let mut values = Vec::new();
    let mut call = false;
    dpc_ir::visit_stmts(&f.body, &mut |st| {
        if let StmtKind::SetResult(e) = &st.kind {
            values.push(pointer_value(e, escaped));
            call |= a0_call(e).is_some();
        }
    });
    if call || values.contains(&PointerValue::Other) {
        // Best effort (not byte-identical): the register-held variable, as
        // before bead domain-pascal-yqsm (no site of these shapes; the
        // slot is the image's where every value is memory or `nil`,
        // KBD_$GET_DESC 0xE1AA92, NET_$FIND_HANDLER 0xE5A178, and as the
        // only statement for a call's A0, MST_$MAP 0xE438BE).
        return Ok((None, false));
    }
    if mode == SlotMode::Auto && !values.contains(&PointerValue::Memory) {
        let local = values.contains(&PointerValue::Local);
        return Ok((None, local && f.result_slot.is_some()));
    }
    match f.result_slot {
        Some(slot) => Ok((Some(slot), false)),
        None => Err(unsupported(
            f.span,
            "a pointer result without a frame slot is",
        )),
    }
}

/// What [`select_body_with`] gives: the body and the reuses found, or the
/// pointer locals to select again held in A0 ([`Selector::a0_locals`]).
enum Selected {
    Body(Body, Vec<(u32, u32)>),
    InA0(Vec<i32>),
    /// Select again with the pointer result variable in its frame slot,
    /// or without it ([`Selector::slot_wanted`]).
    Reslot(SlotMode),
    /// Select again with these register-held locals (frame offsets), read
    /// before the code first assigns them, set to 0 at entry (best effort;
    /// [`select_body_with`] only).
    Predefine(Vec<i32>),
}

/// Whether a body keeps its pointer result variable in its frame slot
/// ([`pointer_result_in_slot`]).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum SlotMode {
    /// As its assignments' values say; a local in its frame slot asks
    /// for [`SlotMode::Force`].
    Auto,
    /// In the slot: a local found there on the first selection.
    Force,
    /// Not in the slot: a register-held local found in slot mode; the
    /// register-held variable of `main` before bead domain-pascal-yqsm
    /// (best effort).
    Off,
}

/// [`select_body_once`], selected again with the register-held locals it
/// finds read before they are assigned given a value at entry
/// ([`Selected::Predefine`]).
fn select_body_with(
    f: &Function,
    plan: CsePlan,
    sched: Schedule,
    in_a0: &[i32],
    overlays: &Overlays,
    slot: SlotMode,
    modes: &[(Span, CallMode)],
    cpu: Cpu,
) -> Result<Selected, Diagnostic> {
    let mut predef: Vec<i32> = Vec::new();
    loop {
        let got = select_body_once(
            f,
            plan.clone(),
            sched,
            in_a0,
            overlays,
            slot,
            modes,
            &predef,
            cpu,
        )?;
        match got {
            Selected::Predefine(o) if o.iter().any(|x| !predef.contains(x)) => predef.extend(o),
            Selected::Predefine(_) => return Err(unsupported(f.span, UNASSIGNED_LOCAL)),
            got => return Ok(got),
        }
    }
}

/// The refusal of a register-held local read before the code first assigns
/// it, under `--strict` ([`Selected::Predefine`]).
const UNASSIGNED_LOCAL: &str = "a register-held local read before the code first assigns it (in \
     a loop, assigned later in its body; or not yet assigned; codegen-patterns 12.5) is";

#[allow(clippy::too_many_arguments)]
fn select_body_once(
    f: &Function,
    plan: CsePlan,
    sched: Schedule,
    in_a0: &[i32],
    overlays: &Overlays,
    slot: SlotMode,
    modes: &[(Span, CallMode)],
    predef: &[i32],
    cpu: Cpu,
) -> Result<Selected, Diagnostic> {
    let mut s = Selector::new(f.span);
    s.cpu = cpu;
    s.call_modes = modes.to_vec();
    s.cse_plan = plan;
    s.overlays = overlays.to_vec();
    s.data_label = crate::emit::data_base_label(&f.data_section);
    if f.loads_data_base {
        s.load_data_base();
    }
    if f.data_absolute {
        // codegen-patterns 4: the only sites are straight-line stores
        // (REM_NAME_$REGISTER_SERVER 0xE4A4AE, AUDIT_$SUSPEND 0xE70DB6).
        if let Some(st) = f
            .body
            .iter()
            .find(|st| !matches!(st.kind, StmtKind::Store { .. }))
        {
            // Refused, also as best effort: a branch or a call would hit the
            // refusal after selection anyway (the absolute base is not
            // loaded again past them; review of bead domain-pascal-5kgg).
            return Err(unsupported(
                st.span,
                "in a routine that addresses its unit's data absolutely (--a5-absolute), a \
                 statement other than an assignment (only straight-line stores are seen, \
                 codegen-patterns 4) is",
            ));
        }
        s.data_absolute = true;
    }
    s.uplevel = f.uplevel_refs.clone();
    s.escaped = escaped_frame_objects(f);
    s.address_slots = f.address_params.clone();
    s.assigned_params = assigned_params(f);
    s.partial_params = partly_read_params(f);
    s.unread_assigned = s
        .assigned_params
        .iter()
        .copied()
        .filter(|&o| {
            let n = f
                .value_params
                .iter()
                .find(|p| p.offset == o)
                .map_or(4, |p| p.ty.bytes());
            !param_read(f, o, n as i32)
        })
        .collect();
    // Labels emit nothing: a body is its other statements.
    let stmts: Vec<&Stmt> = f
        .body
        .iter()
        .filter(|st| !matches!(st.kind, StmtKind::Label(_)))
        .collect();
    let control_only = stmts.len() == 1 && !is_simple(stmts[0]);
    s.multi_body = stmts.len() >= 2 || control_only;
    // The routine's labels and the `goto`s to each ([`Selector::place_user_label`]).
    let mut nlabels = 0;
    dpc_ir::visit_stmts(&f.body, &mut |st| {
        if let StmtKind::Label(l) = st.kind {
            nlabels = nlabels.max(l as usize + 1);
        }
    });
    s.user_labels = vec![None; nlabels];
    s.gotos_total = vec![0; nlabels];
    s.gotos_seen = vec![0; nlabels];
    dpc_ir::visit_stmts(&f.body, &mut |st| {
        if let StmtKind::Goto(l) = st.kind {
            s.gotos_total[l as usize] += 1;
        }
    });
    s.label_clean = label_tails(&f.body, nlabels);
    // The entry loads (their range in `out`) after a block of another
    // data section loaded before them, checked after allocation.
    let mut hoisted: Option<std::ops::Range<usize>> = None;
    if s.multi_body {
        // A body of one `if`, `case` or loop statement loads the by-value
        // parameters it reads at entry as a body of several statements
        // does (codegen-patterns 12.2, "One-statement bodies"; bead
        // domain-pascal-s4a5): KBD_$RCV's nested 0xE1CC64 `move.b
        // (8,A6),D1` before its `case` chain, tty_$i_set_raw_mode 0xE1BF82
        // `move.b (0xc,A6),D0; bpl` (read once, in the condition),
        // PROC2_$SET_CLEANUP 0xE41580 (read in the body only, past a test
        // of a global), DBUF_$UPDATE_VOL 0xE3AAB0 (a `for'), and every
        // other such body surveyed (`tools/localsurvey.py onestmt`); none
        // reads one in its slot.
        // A function of one such statement that assigns a by-value
        // parameter to its result: KBD_$RCV's nested 0xE1CC64 keeps `ch`
        // in D1 apart from the result in D0 (`move.b D1b,D0b` at
        // 0xE1CCBA, the selector widened into D0), where the allocator's
        // result variable shares a register with a parameter it is
        // assigned from (0xE15222; codegen-patterns 12.4 R5).  Which
        // applies is not settled (bead domain-pascal-0zo8).
        if control_only && f.result.is_some() {
            let mut copies_param = false;
            dpc_ir::visit_stmts(&f.body, &mut |st| {
                if let StmtKind::SetResult(e) = &st.kind {
                    let mut e = e;
                    while let Expr::Convert { value, .. } = e {
                        e = value;
                    }
                    if let Expr::Load {
                        addr: Addr::Frame(o),
                        ..
                    } = e
                    {
                        copies_param |= f.value_params.iter().any(|p| p.offset == *o);
                    }
                }
            });
            if copies_param {
                best_effort(
                    f.body[0].span,
                    "a function body of one `if`, `case` or loop statement that assigns a \
                     by-value parameter to the result (kept apart at 0xE1CCBA, shared at \
                     0xE15222; not settled, codegen-patterns 12.2) is",
                )?;
            }
        }
        // A parameter loaded at entry and live across a call is held in a
        // callee-saved register by the allocator (codegen-patterns 12.4
        // R3: PROC1_$SET_TYPE 0xE152F2 D2, D3 around a `jsr`;
        // module-local 0xE32B76, 0xE32B7E A2, D2 around three).
        // The block of another data section that the first statement
        // reaches is loaded before the parameters loaded at entry and the
        // static link, as A5 is (KBD_$INIT 0xE3336A `movea.l #0xE2DDE4,A0`
        // before 0xE33370 `movea.l (8,A6),A2`; NETWORK_$READ_SERVICE
        // 0xE71D80 before `movea.l (8,A6),A0`; the RINGLOG_ module-local
        // 0xE721D4 before `movea.l (A6),A2`; no routine loads its
        // parameters first when its first statement starts with the block,
        // `tools/sectsurvey.py otherdata`).
        // Where the block of a first statement that reaches it otherwise
        // is loaded relative to those loads is not seen: refused below.
        let first = stmts.first().copied();
        if let Some(section) = first.and_then(first_other_static) {
            s.other_base(&section)?;
        }
        let pinned = s.pinned.len();
        let entry_start = s.out.len();
        s.entry_loads(f)?;
        if !s.other_base_loads.is_empty() {
            hoisted = Some(entry_start..s.out.len());
        }
        if s.pinned.len() > pinned
            && first.is_some_and(|st| first_other_static(st).is_none() && mentions_other_static(st))
        {
            best_effort(
                first.unwrap().span,
                "a first statement that reaches another data section's block other than by a \
                 constant store, in a routine that loads parameters at entry (which the \
                 original loaded first is not seen, codegen-patterns 11) is",
            )?;
        }
        s.entry_regs = s.pinned.iter().map(|&(_, r)| r).collect();
        if s.pinned.len() > pinned {
            s.entry_end = Some(entry_start..s.out.len());
        }
        // A function body of several statements holds its result variable
        // in a register up to the epilogue (codegen-patterns 3, "Result
        // variable"; [`Selector::set_result_web`]).
        s.result_web = f.result.is_some();
    }
    s.result_positions = result_positions(&f.body);
    if s.result_web {
        (s.ptr_slot, s.slot_allowed) =
            pointer_result_in_slot(f, &s.escaped, s.result_positions, slot)?;
    }
    s.load_link(f)?;
    s.param_copies(f)?;
    let reg_locals = register_locals(f);
    s.reg_locals = reg_locals.iter().map(|&(o, _)| o).collect();
    // The value-parameter copies held in a register stand for their
    // variable as a register-held local does ([`held_param_copies`]).
    s.reg_locals.extend(held_param_copies(f));
    for &(o, web) in &reg_locals {
        if web {
            let d = s.alloc_d()?;
            s.webs.push((o, d));
            if predef.contains(&o) {
                // Read before the code first assigns it: 0 at entry, a
                // defined value for a variable Pascal leaves undefined
                // ([`Selected::Predefine`]).
                s.out.push(Insn::Moveq { value: 0, dst: d });
            }
        }
    }
    s.ptr_locals = loop_pointer_locals(f, &s.reg_locals)
        .into_iter()
        .map(|o| (o, None))
        .collect();
    // A `with` record reached at run time: its pointer, computed once,
    // held in an address register for the body (codegen-patterns 5.2,
    // "`with`"; NETLOG_$LOG_IT 0xE71BCA).
    s.ptr_locals.extend(f.with_temps.iter().map(|&o| (o, None)));
    let mut taken = s.reg_locals.clone();
    taken.extend(s.ptr_locals.iter().map(|&(o, _)| o));
    let call_ptrs = call_pointer_locals(f, &taken);
    for &o in &call_ptrs {
        // An integer local of [`integer_call_local`] is parked, where a
        // call follows too; a pointer local that no call follows is held
        // in A0 itself when allocation finds it there.
        let integer = f
            .scalar_locals
            .iter()
            .any(|l| l.offset == o && l.ty != Scalar::POINTER);
        if in_a0.contains(&o) {
            s.a0_locals.push(o);
        } else if integer {
            s.parked.push(Park {
                off: o,
                d: None,
                home: None,
            });
        } else {
            s.ptr_locals.push((o, None));
        }
    }
    if s.cpu.is_68020() {
        // MC68020 mode: every other dereferenced pointer local in an
        // address register ([`free_pointer_locals`]).
        taken.extend(call_ptrs.iter().copied());
        let free = free_pointer_locals(f, &taken);
        if !free.is_empty() {
            best_effort(
                f.span,
                "a pointer local assigned other than from pointer functions, held in an address \
                 register for the whole body under `-cpu mathchip` (the SAU9 image holds such \
                 locals in a data or an address register by a rule not found: SCSI_$C90_INT \
                 0x3C4A5826 A3 and 0x3C4A58D2 D4, SCSI_$RESET_DEVICE 0x3C4A650C D2 and \
                 0x3C4A6518 A2; codegen-patterns 12.5; bead domain-pascal-jqp0) is",
            )?;
            s.ptr_locals.extend(free.into_iter().map(|o| (o, None)));
        }
    }
    s.entry_tail = s.out.len().checked_sub(1);
    let body = s.seq(f, &f.body, Tail::END);
    if let Some(mode) = s.slot_wanted {
        return Ok(Selected::Reslot(mode));
    }
    body?;
    // An element address of another unit's array or through a loaded
    // pointer formed as a value ([`Selector::lea_into`]): read twice or
    // more, or live across a call, the allocator's choice of its register
    // is the image's (codegen-patterns 5.2, "The element's address as a
    // value"; `tools/regalloc.py elemaddr`): read twice or more with no
    // call, it takes the lowest register free over its range, the dying
    // base's counted free, where that and R2 differ 129 times against 6
    // (XPD_$FIND_INDEX 0xE5AF60 `lea (0,A0,D1.l),A0`), and with R4(c) for
    // a last read that is a call's argument 197 of 208 sites fit
    // (MMAP_$FREE_LIST 0xE0CB50 `lea (0,A0,D0.l),A2`, `pea (-8192,A2);
    // bsr.w`); live across a call, the lowest callee-saved register free
    // (R3), the base in another 122 times and in it 21 (MMAP_$AVAIL
    // 0xE0CC80 `lea (0,A0,D0.l),A2`).  Read once in no call's range it fits
    // the first 98 times and R2 99 times (0xE32CD6 `lea (78,A0,D3.l),A0`,
    // stored; 0xE1C242 `lea (0,A0,D0.w),A1`, stored), neither 114
    // (SIO6509_$INIT 0xE33548 `lea (-32,A3,D0.w),A3`); what decides is A1's
    // state with the base in A0, checked after allocation
    // ([`once_elem_lea`], bead domain-pascal-1ibr).
    let mut once_leas: Vec<(usize, Span)> = Vec::new();
    for &(k, span) in &s.elem_leas {
        let Insn::Lea { dst, .. } = s.out[k] else {
            unreachable!("an element address's `lea`")
        };
        let r = Reg::A(dst);
        let mut reads = 0;
        let mut call = false;
        let mut across = false;
        for i in &s.out[k + 1..] {
            let a = crate::regs::access(i);
            if a.uses.contains(&r) {
                reads += 1;
                across |= call;
            }
            if a.defs.contains(&r) && !a.uses.contains(&r) {
                break;
            }
            call |= matches!(i, Insn::Jsr(_) | Insn::Bsr { .. });
        }
        if reads < 2 && !across {
            match once_elem_shape(&s.out, k) {
                Ok(()) => once_leas.push((k, span)),
                // Best effort (bead domain-pascal-5kgg): the allocator's
                // register for the address.
                Err(w) => best_effort(span, w)?,
            }
        }
    }
    if !s.other_base_loads.is_empty()
        && s.out
            .iter()
            .any(|i| matches!(i, Insn::Branch { .. } | Insn::Dbf { .. } | Insn::Label(_)))
    {
        // Across a branch target the image both keeps the block's register
        // (NETWORK_$READ_SERVICE 0xE71D9A after an `if`; loops, TPAD_$INIT
        // 0xE335A4) and loads it again (AST_$ACTIVATE_ASTE_CANNED 0xE2F266,
        // NAME_$INIT 0xE317C0, NET_IO_$BOOT_DEVICE 0xE31C66): not settled
        // (codegen-patterns 11).
        best_effort(
            f.span,
            "a routine that reaches another data section's block and branches (where the \
             block's address is loaded again is not settled, codegen-patterns 11) is",
        )?;
    }
    if f.data_absolute
        && s.out.iter().any(|i| {
            matches!(
                i,
                Insn::Branch { .. } | Insn::Dbf { .. } | Insn::Jsr(_) | Insn::Bsr { .. }
            )
        })
    {
        // Where the base register would live across a call, and how a
        // branch would place its `lea`, is not seen (codegen-patterns 4).
        return Err(unsupported(
            f.span,
            "a routine that addresses its unit's data absolutely (--a5-absolute) and calls or \
             branches is",
        ));
    }
    // A0 given as a pointer local's base must reach its use: nothing of
    // the statement may write A0 first (an M$ARITH call among the
    // operands, say).
    for &(at, span) in &s.a0_bases {
        let a0 = Reg::A(0);
        let used = s.out[at..]
            .iter()
            .position(|i| crate::regs::access(i).uses.contains(&a0));
        let written = s.out[at..]
            .iter()
            .position(|i| crate::regs::access(i).defs.contains(&a0));
        if used.is_none() || matches!((used, written), (Some(u), Some(w)) if w < u) {
            return Err(unsupported(
                span,
                "an expression that writes A0 after reading a pointer local through it is",
            ));
        }
    }
    if let Some(l) = s.epilogue {
        s.place(l);
    }
    if let (Some(web), Some(res)) = (s.web, f.result) {
        // The result variable's register into the result register, at
        // the start of the epilogue, where a `return` branches to
        // (PKT_$NEXT_ID 0xE124D0 `move.w D2,D0`; NETBUF_$RTNVA 0xE0ED60
        // `move.l D2,D0`; 62 of the 73 such moves of `tools/resultsurvey.py
        // list reg` are from a callee-saved register).  Dropped when the
        // allocator gives the variable D0 itself (PARITY_$CHK_IO 0xE0B19C
        // `moveq #1,D0; bra.s`; PROC1_$SUSPENDP 0xE14886 `st D0`).
        s.result_moves.push(s.out.len());
        s.out.push(Insn::Move {
            size: size_of(res.ty.width),
            src: Ea::Reg(Reg::D(web)),
            dst: Ea::Reg(Reg::D(0)),
        });
    }
    let mut web_a_move = None;
    if let Some(slot) = s.ptr_slot {
        // A pointer result variable in its frame slot, into A0 at the start
        // of the epilogue, where a `return` branches to (KBD_$GET_DESC
        // 0xE1AA98 `movea.l (-8,A6),A0`, the error paths' `bra.s` at
        // 0xE1AA44 and 0xE1AA6E; codegen-patterns 3, "Pointer results").
        s.out.push(Insn::Movea {
            size: Size::L,
            src: Ea::Disp(slot, FP),
            dst: 0,
        });
    } else if let Some(web) = s.web_a {
        web_a_move = Some(s.out.len());
        // A pointer result variable into A0 at the start of the epilogue
        // (DISK_$GET_BLOCK 0xE3BBCA `movea.l A2,A0`; codegen-patterns 3,
        // "Pointer results": 12 of the 16 such moves are from A2).
        s.result_moves.push(s.out.len());
        s.out.push(Insn::Movea {
            size: Size::L,
            src: Ea::Reg(Reg::A(web)),
            dst: 0,
        });
    }
    // Branches to a `bra` go to its target, and a `bra` no longer
    // reached is replaced by a label nothing names (dropped below with
    // the other unused labels; codegen-patterns 7.1, "Branch threading").
    thread_branches(&mut s.out, &mut s.next_label, &s.before_bra, f.span)?;
    // Labels nothing branches to (the join after a `then` part that ends
    // in `return`, ...) are dropped; they emit no bytes either way.
    // A `case` table's entries name their targets like branches (a
    // target before a `bra` is refused, [`thread_branches`]); its own
    // label is named by the dispatch.
    let used: Vec<u32> = s
        .out
        .iter()
        .flat_map(|i| match i {
            Insn::Branch { label, .. } | Insn::Dbf { label, .. } => vec![*label],
            Insn::TableIndex { table, .. } => vec![*table],
            Insn::TableEntry { target, .. } => vec![*target],
            _ => vec![],
        })
        .collect();
    // An `exit` or `next` whose target is the very next instruction (a
    // `next` ending a loop body, an `exit` before an inner loop's end):
    // whether the original emitted the branch is not known.
    for &(at, span) in &s.loop_jumps {
        let label = match s.out[at] {
            Insn::Branch { label, .. } => label,
            // Dropped by [`thread_branches`]: the branches to it now go
            // where it went, and nothing reaches it.
            Insn::Label(_) => continue,
            _ => unreachable!("loop_jumps records branches"),
        };
        let next = s.out[at + 1..]
            .iter()
            .take_while(|i| matches!(i, Insn::Label(_) | Insn::Align4))
            .any(|i| matches!(i, Insn::Label(l) if *l == label));
        if next {
            best_effort(
                span,
                "an `exit` or `next` that would branch to the next instruction is",
            )?;
        }
    }
    // Likewise a `goto` to the next instruction (`goto L; L: ...`, or
    // `if c then goto L` before it): not seen.
    debug_assert_eq!(s.open_back, 0, "every backward goto selected");
    for &(at, span) in &s.goto_jumps {
        let label = match s.out[at] {
            Insn::Branch { label, .. } => label,
            // Dropped by [`thread_branches`]: the branches to it now go
            // where it went, and nothing reaches it.
            Insn::Label(_) => continue,
            _ => unreachable!("goto_jumps records branches"),
        };
        let next = s.out[at + 1..]
            .iter()
            .take_while(|i| matches!(i, Insn::Label(_) | Insn::Align4))
            .any(|i| matches!(i, Insn::Label(l) if *l == label));
        if next {
            best_effort(
                span,
                "a `goto` that would branch to the next instruction is",
            )?;
        }
    }
    // References to volatile objects (ref 3.15.1-3.15.3): the
    // instructions that reference one, kept in order by the scheduler;
    // none of them a read-modify-write of a device object.
    let volatile_insns = volatile_references(&s.out, &s.volatile_eas, f.span)?;
    // Phase 1b: physical registers (`regs.rs`, codegen-patterns 12.4).
    let exit: &[Reg] = match f.result {
        Some(ResultSpec {
            class: ResultClass::Data,
            ..
        }) => &[Reg::D(0)],
        Some(ResultSpec {
            class: ResultClass::Address,
            ..
        }) => &[Reg::A(0)],
        _ => &[],
    };
    // The registers of the pointer locals assigned from calls: held
    // through a call whose arguments use them last, in a body with
    // branches too ([`call_pointer_locals`]).
    let held_ptrs: Vec<Reg> = s
        .ptr_locals
        .iter()
        .filter(|(o, _)| call_ptrs.contains(o))
        .filter_map(|&(_, a)| a.map(Reg::A))
        .chain(
            s.parked
                .iter()
                .filter_map(|p| p.home.map(|(a, _)| Reg::A(a))),
        )
        .collect();
    // The registers holding another data section's block: not held
    // through a call whose arguments use them last (XNS_IDP_$INIT
    // 0xE3026E..0xE30280: `movea.l #0xE2B314,A0` in one statement,
    // `pea (0x520,A0)` for the call of the next; MAC_OS_$INIT 0xE2F504),
    // loaded again after it ([`Selector::other_base`]).
    let blocks: Vec<Reg> = s
        .other_base_loads
        .iter()
        .filter_map(|&i| match s.out[i] {
            Insn::Movea { dst, .. } => Some(Reg::A(dst)),
            _ => None,
        })
        .collect();
    // A block's register loaded before a call and read after it (`l := b
    // + g(x)`: the operand's base taken before the call is evaluated):
    // the survey sees no block register live across a call, every use
    // after one follows a load of its own (codegen-patterns 11); where the
    // original loads the block for such an expression is not seen.
    if !blocks.is_empty() {
        let live_out = crate::regs::liveness(&s.out, exit, &[]);
        if let Some(&(_, _, span)) = s.call_stmts.iter().find(|&&(_, c, _)| {
            blocks
                .iter()
                .any(|&r| live_out[c].contains(&crate::regs::RegKey(r)))
        }) {
            best_effort(
                span,
                "another data section's block reached on both sides of a call in one statement \
                 (where the original loads the block is not seen, codegen-patterns 11) is",
            )?;
        }
    }
    // The registers of `with` records' addresses ([`Function::with_temps`]),
    // those of an array element apart, and of register-held locals (webs
    // and pinned locals, [`register_locals`]), told apart by
    // [`held_through_calls`].
    let with_regs: Vec<Reg> = s
        .ptr_locals
        .iter()
        .filter(|(o, _)| f.with_temps.contains(o))
        .filter_map(|&(_, a)| a.map(Reg::A))
        .collect();
    let with_elem_regs: Vec<Reg> = s
        .ptr_locals
        .iter()
        .filter(|(o, _)| f.with_temps.contains(o) && s.elem_ptrs.contains(o))
        .filter_map(|&(_, a)| a.map(Reg::A))
        .chain(s.held_elem_regs.iter().map(|&a| Reg::A(a)))
        .collect();
    let local_regs: Vec<Reg> = s
        .webs
        .iter()
        .map(|&(_, d)| Reg::D(d))
        .chain(
            s.pinned
                .iter()
                .filter(|(o, _)| s.reg_locals.contains(o))
                .map(|&(_, r)| r),
        )
        .chain(
            s.ptr_locals
                .iter()
                .filter(|(o, _)| !f.with_temps.contains(o))
                .filter_map(|&(_, a)| a.map(Reg::A)),
        )
        .collect();
    let mut holds = held_through_calls(
        &s.out,
        &s.call_stmts,
        exit,
        HeldKinds {
            link: s.link.map(Reg::A),
            ptrs: &held_ptrs,
            blocks: &blocks,
            params: &s.entry_regs,
            data_ptrs: &s.data_ptr_regs,
            withs: &with_regs,
            with_elems: &with_elem_regs,
            locals: &local_regs,
        },
    )?;
    // A parked local's data register stays the local's until its last
    // dereference, though only the address register is read there: the
    // image leaves D0 alone over that range (TTY_$K_SET_INPUT_FLAG
    // 0xE6768E..0xE676A2 builds its set in D1 and D2, saving D2, with D0
    // free; TTY_$K_SET_DELAY 0xE67A42 `move.w (A2),D1`; the DIR_
    // module-local 0xE52394 at 0xE5243E `move.w (22,A0),D1`).
    for p in &s.parked {
        if let (Some((d, _)), Some((a, at))) = (p.d, p.home) {
            for (i, insn) in s.out.iter().enumerate().skip(at + 1) {
                if matches!(insn, Insn::Jsr(_) | Insn::Bsr { .. }) {
                    // Parked where a call follows: the call clobbers D0, which is free
                    // from there (TTY_$K_FLUSH_INPUT 0xE1C0BE `move.w
                    // D0,(-6,A6)`, the spin lock's token).
                    break;
                }
                if crate::regs::access(insn).uses.contains(&Reg::A(a)) {
                    holds.push((i, Reg::D(d)));
                }
            }
        }
    }
    let (mut apart, mut late, prefix) = fresh_slot_loads(&s.out, &s.fresh);
    let (args_apart, args_soft, long_list) = argument_list_loads(&s.out, &s.call_stmts)?;
    // The prefix's slot loads, and those of an argument list longer than
    // the address registers, may reuse the least recently written of the
    // registers dead slot loads hold when none is otherwise free
    // ([`crate::regs::allocate_apart`]'s `recycle`); not a pair an
    // argument list of at most five keeps apart.
    let mut recycle: Vec<(Reg, Reg)> = prefix
        .into_iter()
        .filter(|p| !args_apart.contains(p) && !args_apart.contains(&(p.1, p.0)))
        .collect();
    recycle.extend(args_soft.iter().copied());
    apart.extend(args_apart);
    apart.extend(args_soft.iter().copied());
    for &d in &s.callee_only {
        apart.extend([(Reg::D(d), Reg::D(0)), (Reg::D(d), Reg::D(1))]);
    }
    apart.extend(s.colour_apart.iter().copied());
    // A register-held local read before the first instruction that
    // assigns it (a read the loop's back edge reaches, or of a local not
    // yet assigned): its register is live into the body.  Where the
    // original colours such a value is not known.  Best effort (not
    // byte-identical; bead domain-pascal-trdz): selected again with the
    // local set to 0 at entry (Pascal leaves its value undefined; TERM_
    // $INQUIRE's image reads a frame word nothing clears, 0xE6713C).
    let mut unassigned = Vec::new();
    for &(o, d) in &s.webs {
        let r = Reg::D(d);
        let first = s.out.iter().find_map(|i| {
            let a = crate::regs::access(i);
            if a.uses.contains(&r) {
                Some(true)
            } else if a.defs.contains(&r) {
                Some(false)
            } else {
                None
            }
        });
        if first == Some(true) {
            unassigned.push(o);
        }
    }
    if !unassigned.is_empty() {
        best_effort(f.span, UNASSIGNED_LOCAL)?;
        return Ok(Selected::Predefine(unassigned));
    }
    let mut first = s.web.map(|w| (Reg::D(w), s.entry_regs.clone()));
    // A pointer local assigned a call's result before a parameter that
    // dies in the same block (codegen-patterns 12.4 R1b, `regs.rs`).
    let results: Vec<usize> = s
        .ptr_defs
        .iter()
        .filter(|(o, _, _)| call_ptrs.contains(o))
        .map(|&(_, k, _)| k)
        .collect();
    let mut after = call_results_first(&s.out, exit, &holds, &results, &s.entry_regs);
    after.extend(s.colour_after.iter().copied());
    // The pointer locals of `call_pointer_locals` that could stay in A0
    // itself: nothing writes the physical A0
    // from the copy `movea.l A0,An` to the copy's last use.
    let a0_free: Vec<i32> = s
        .ptr_defs
        .iter()
        .filter(|(o, _, _)| call_ptrs.contains(o))
        .filter(|&&(_, k, _)| {
            let Some(Insn::Movea { dst: v, .. }) = s.out.get(k) else {
                return false;
            };
            let v = Reg::A(*v);
            let Some(last) = s
                .out
                .iter()
                .rposition(|i| crate::regs::access(i).uses.contains(&v))
            else {
                return false;
            };
            // In a loop the copy's range is not the straight run from it
            // to its last use ([`live_range`]; a use before the copy,
            // reached round the loop, panicked here before bead
            // domain-pascal-yqf6's review).
            let (lo, hi) = live_range(&s.out, v, k, last);
            if hi < last {
                return false;
            }
            !s.out[lo..=hi].iter().enumerate().any(|(j, i)| {
                lo + j != k
                    && (matches!(i, Insn::Jsr(_) | Insn::Bsr { .. })
                        || crate::regs::access(i).defs.contains(&Reg::A(0)))
            })
        })
        .map(|&(o, _, _)| o)
        .collect();
    let pre = s.out.clone();
    // A body coloured with spills ([`crate::spill`]): the reloads before
    // and the stores after each of its instructions, spliced in when the
    // body is put together below, and the frame bytes they take.
    let mut spills: Option<(Vec<Vec<Insn>>, Vec<Vec<Insn>>)> = None;
    let mut spill_bytes = 0;
    let first_try = allocate_apart(
        &mut s.out,
        exit,
        &holds,
        &apart,
        first.clone(),
        &after,
        &s.colour_coalesce,
        &recycle,
    );
    // The over-long argument list's colouring, when that is the cause
    // (below): the body, `apart` and `recycle` without the list's pairs.
    let mut long_out: Option<(Vec<Insn>, RegSet, Vec<(Reg, Reg)>, Vec<(Reg, Reg)>)> = None;
    let first_try = first_try.map_err(|what| {
        // A pointer result variable with no callee-saved address register
        // free is in its frame slot in the image (BAT_$ALLOC_VTOCE
        // 0xE3AEDA `clr.l (-0x14,A6)` and MST_$REMAP_PRIVI 0xE43A26 `clr.l
        // (-0x10,A6)` for `nil`, A2-A5 saved; codegen-patterns 3, "`nil`
        // results"), which `dpc` does not model.
        let what = if !s.nil_results.is_empty() && long_list.is_none() {
            format!(
                "{what} (a pointer result variable is in its frame slot where no callee-saved \
                 address register is free: BAT_$ALLOC_VTOCE 0xE3AEDA, MST_$REMAP_PRIVI \
                 0xE43A26)"
            )
        } else {
            what
        };
        // The over-long argument list is the cause when the body colours
        // without its loads kept apart at all.
        let Some(span) = long_list else {
            return unsupported(f.span, &what);
        };
        let free: Vec<(Reg, Reg)> = apart
            .iter()
            .filter(|p| !args_soft.contains(p))
            .copied()
            .collect();
        let rest: Vec<(Reg, Reg)> = recycle
            .iter()
            .filter(|p| !args_soft.contains(p))
            .copied()
            .collect();
        let mut out = pre.clone();
        match allocate_apart(
            &mut out,
            exit,
            &holds,
            &free,
            first.clone(),
            &after,
            &s.colour_coalesce,
            &rest,
        ) {
            Ok(v) => {
                long_out = Some((out, v, free, rest));
                long_argument_list(span)
            }
            Err(_) => unsupported(f.span, &what),
        }
    });
    let mut saves = match first_try {
        Ok(v) => v,
        Err(refusal) if dpc_syntax::diag::is_strict() => return Err(refusal),
        // Best effort (bead domain-pascal-5kgg): the argument list's loads
        // not kept apart (the order of their registers is not settled).
        Err(refusal) if long_out.is_some() => {
            dpc_syntax::diag::best_effort(refusal)?;
            let (out, v, free, rest) = long_out.take().unwrap();
            s.out = out;
            apart = free;
            recycle = rest;
            v
        }
        // Best effort: coloured without the constraints of form (values
        // kept apart, recycled, coloured first or after another), then
        // also without the holds through calls (which only lengthen live
        // ranges); every colouring of the live ranges is correct.  A body
        // that does not colour even so has values spilled (below).
        Err(refusal) => {
            s.out = pre.clone();
            let mut got = allocate_apart(
                &mut s.out,
                exit,
                &holds,
                &[],
                None,
                &[],
                &s.colour_coalesce,
                &[],
            );
            if got.is_err() {
                s.out = pre.clone();
                got = allocate_apart(
                    &mut s.out,
                    exit,
                    &[],
                    &[],
                    None,
                    &[],
                    &s.colour_coalesce,
                    &[],
                );
                if got.is_ok() {
                    holds.clear();
                }
            }
            let v = match got {
                Ok(v) => v,
                // Best effort (not byte-identical): values spilled to frame
                // temporaries below the locals (`crate::spill`, bead
                // domain-pascal-qea9); the original has no such spills
                // (bead domain-pascal-ei42).
                Err(_) => {
                    let Ok(sp) = crate::spill::allocate_spilling(
                        &pre,
                        exit,
                        &s.colour_coalesce,
                        crate::M68k::link_size(f.frame_size),
                        &s.address_slots,
                    ) else {
                        return Err(refusal);
                    };
                    holds.clear();
                    s.out = sp.insns;
                    spill_bytes = sp.bytes;
                    spills = Some((sp.before, sp.after));
                    sp.saves
                }
            };
            dpc_syntax::diag::best_effort(refusal)?;
            apart.clear();
            recycle.clear();
            after.clear();
            first = None;
            v
        }
    };
    // A slot loaded late into a register that holds a dead slot load on
    // every path passes over it ([`pass_dead_slot_loads`], 12.4 R4(b));
    // the body is coloured again with the slot kept apart from those loads.
    let mut passed: Vec<usize> = Vec::new();
    // Best effort (bead domain-pascal-5kgg): the once-read element
    // addresses whose A1 colouring is given up, the previous colouring kept.
    let mut once_skip: Vec<usize> = Vec::new();
    // A spilled body ([`crate::spill`]): the checks below that compare
    // the registers of its instructions (fidelity checks of forms the
    // image shows) are skipped where a spilled value's reloads and stores
    // take other registers than the selector expects; the code is correct
    // either way.
    let spilled = spills.is_some();
    if spilled {
        // A spilled body is not coloured again for these forms (which
        // colour `pre`, without the spills), nor checked for the late slot
        // loads' registers: best effort already.
        once_leas.clear();
        late.clear();
    }
    loop {
        if spilled {
            break;
        }
        let more = pass_dead_slot_loads(&pre, &s.out, &late, &apart);
        if more.is_empty() {
            // An element address read once that the image puts in A1
            // rather than in its base's A0 ([`once_elem_lea`]): coloured
            // again with it kept apart from the base, one at a time in
            // order, since A1 taken by one makes it dirty for the next.
            let mut elem_more = None;
            for &(k, span) in &once_leas {
                if once_skip.contains(&k) {
                    continue;
                }
                let got = match once_elem_lea(&pre, &s.out, k, exit, &holds) {
                    Ok(p) => p,
                    Err(w) => {
                        best_effort(span, w)?;
                        None
                    }
                };
                if let Some(pair) = got {
                    if apart.contains(&pair) {
                        best_effort(span, ONCE_LEA_NOT_A1)?;
                        continue;
                    }
                    elem_more = Some((pair, span, k));
                    break;
                }
            }
            let Some((pair, span, k)) = elem_more else {
                break;
            };
            apart.push(pair);
            let prev = std::mem::replace(&mut s.out, pre.clone());
            match allocate_apart(
                &mut s.out,
                exit,
                &holds,
                &apart,
                first.clone(),
                &after,
                &s.colour_coalesce,
                &recycle,
            ) {
                Ok(v) => saves = v,
                Err(_) => {
                    // Best effort: the colouring before, which is correct.
                    best_effort(span, ONCE_LEA_NOT_A1)?;
                    apart.pop();
                    s.out = prev;
                    once_skip.push(k);
                }
            }
            continue;
        }
        let before = apart.len();
        for (k, pair) in more {
            if !passed.contains(&k) {
                passed.push(k);
            }
            apart.push(pair);
        }
        let prev = std::mem::replace(&mut s.out, pre.clone());
        match allocate_apart(
            &mut s.out,
            exit,
            &holds,
            &apart,
            first.clone(),
            &after,
            &s.colour_coalesce,
            &recycle,
        ) {
            Ok(v) => saves = v,
            Err(_) => {
                // Best effort (bead domain-pascal-5kgg): the colouring
                // before, which is correct; the dead slot loads stay passed
                // over.
                dpc_syntax::diag::best_effort(late_slot_refusal(
                    late.iter()
                        .find(|l| passed.contains(&l.0))
                        .map_or(f.span, |l| l.2),
                ))?;
                apart.truncate(before);
                s.out = prev;
                break;
            }
        }
    }
    check_assigned_flags(&s.out, &s.flag_moves)?;
    // After allocation, which renames registers in place and keeps the
    // indices (the flags model, `sched::cc_effect`, takes physical ones).
    check_kept_flags(&s.out, &s.kept_flags)?;
    // Each element address read once, with its read: still adjacent after
    // scheduling, the shape [`once_elem_lea`] decided on.
    let once_pairs: Vec<(Insn, Insn, Span)> = once_leas
        .iter()
        .map(|&(k, span)| (s.out[k].clone(), s.out[k + 1].clone(), span))
        .collect();
    // A block element second of the unit's array and its count's `moveq`
    // ([`Selector::note_block_count`]).
    let elem_count_pairs: Vec<(Insn, Insn, Span)> = s
        .elem_counts
        .iter()
        .map(|&(k, c, span)| (s.out[k].clone(), s.out[c].clone(), span))
        .collect();
    let elem_value_triples: Vec<(Insn, Insn, Span)> = s
        .elem_value_bases
        .iter()
        .map(|&(m, p, span)| (s.out[m].clone(), s.out[p].clone(), span))
        .collect();
    let zext_triples: Vec<([Insn; 3], Span)> = s
        .zext_bases
        .iter()
        .map(|&(c, m, b, span)| ([s.out[c].clone(), s.out[b].clone(), s.out[m].clone()], span))
        .collect();
    // Not in a spilled body: the count's two moves name the reload and
    // store values of a spilled count, not one register.
    let count_copies: &[(usize, usize, Span)] = if spilled { &[] } else { &s.count_copies };
    for &(b, k, span) in count_copies {
        count_copy_check(&s.out[b], &s.out[k], span)?;
    }
    for &(lea, second, span) in &s.held_firsts {
        // The pointer held for a block's first address dies at its `lea
        // (An),Am` and the second address took An: the image never does
        // (17 of 17 such sites; ACL_ 0xE44E0A `movea.l #ACL_$DIR_ACL,A2`
        // past a dead A0, CAL_$WRITE_TIMEZONE 0xE3E628 `lea (A5),A3`;
        // codegen-patterns 5.2, "Block addresses").
        let held = match &s.out[lea] {
            Insn::Lea {
                src: Ea::Ind(r), ..
            } => Some(*r),
            _ => None,
        };
        let taken = match &s.out[second] {
            Insn::Lea { dst, .. } | Insn::Movea { dst, .. } => Some(*dst),
            _ => None,
        };
        if held.is_some() && held == taken {
            best_effort(
                span,
                "a block's second address in the register of the pointer held for its first, \
                 which dies at the first's `lea (An),Am` (the image passes it over, 17 of 17: \
                 0xE44E0A, 0xE3E628; the register it takes is not modelled, bead \
                 domain-pascal-76uw) is",
            )?;
        }
    }
    if let Some(range) = hoisted {
        // A parameter loaded at entry into a scratch address register
        // after the block's load: the one such site has the parameter in
        // the lower register, `movea.l #0xE248FC,A1; movea.l (8,A6),A0`
        // (NETWORK_$READ_SERVICE 0xE71D80), against the lowest-free
        // allocation in definition order that gives the block A0 here;
        // the sites that agree hold the parameter or static link in A2
        // (KBD_$INIT 0xE3336A, the RINGLOG_ module-local 0xE721D4).  Not
        // settled (codegen-patterns 11, "Placement at entry").
        if s.out[range].iter().any(|i| {
            crate::regs::access(i)
                .defs
                .iter()
                .any(|r| matches!(r, Reg::A(0) | Reg::A(1)))
        }) {
            best_effort(
                f.span,
                "a parameter loaded at entry into A0 or A1 after another data section's block \
                 (which of the two takes the lower register is not settled, codegen-patterns 11) \
                 is",
            )?;
        }
    }
    // Not in a spilled body: the copies' dataflow does not see the
    // spills' reloads (keeping a copy is correct).
    let dropped = if spills.is_some() {
        Vec::new()
    } else {
        reuse_pointer_copies(&mut s.out, &s.ptr_copies)
    };
    if !dropped.is_empty() {
        // A register only a dropped copy took is not saved.
        let mut used = RegSet::of(&[Reg::A(5)]);
        for i in &s.out {
            let a = crate::regs::access(i);
            for r in a.uses.iter().chain(a.defs.iter()) {
                used.insert(*r);
            }
        }
        saves = saves.intersection(used);
    }
    for &(k, span) in &s.copy_blocks {
        // A block copy of a value parameter is seen from A0 into A1 only
        // (`tools/framesurvey.py`-style search of `movea.l (d,A6),An; lea
        // (k,A6),Am; move (An)+,(Am)+`: 31 slot copies A0 to A1,
        // XPD_$SET_PTRACE_OPTS 0xE5AFB0, OS_$INIT 0xE33808; the three
        // others in nested routines or after a branch).  Where an earlier
        // copy or an entry load holds A0 or A1, which registers the
        // original takes is not known (codegen-patterns 1.2).
        let from_a0 = matches!(s.out.get(k), Some(Insn::Movea { dst: 0, .. }));
        let into_a1 = matches!(s.out.get(k + 1), Some(Insn::Lea { dst: 1, .. }));
        if !(from_a0 && into_a1) {
            best_effort(
                span,
                "a block copy of a value parameter passed by address while an earlier copy or \
                 an entry load holds A0 or A1 (only `A0` to `A1` is seen, codegen-patterns 1.2) \
                 is",
            )?;
        }
    }
    let mut to_a0 = Vec::new();
    // Not in a spilled body: a pointer local there stays where it was
    // coloured (selecting again with it in A0 could spill it again).
    let ptr_defs: &[(i32, usize, Span)] = if spilled { &[] } else { &s.ptr_defs };
    for &(o, k, span) in ptr_defs {
        // A pointer local assigned from calls that no call follows, in A0
        // or A1 by allocation: kept in A0 itself, the copy dropped
        // (TTY_$I_INQ_RAW 0xE67414 `move.b (1241,A0),(A1)`, the out
        // parameter's slot in A1; TTY_$K_INQ_FLAGS 0xE674BA; beads
        // domain-pascal-yzxr, -78n2).  The image's D0 form of such locals
        // (`move.l A0,D0` after the call, `movea.l D0,A0` where it is
        // dereferenced: TTY_$K_INQ_FUNC_ENABLED 0xE6763C / 0xE67642) is
        // that of a 4-byte integer local ([`Park`]); a pointer local is
        // no longer held so (codegen-patterns 3, "Pointer locals held in
        // D0").  The copies to A1 where D0 is busy (0xE4D7FC, 0xE528CE)
        // are not modelled.  One in a callee-saved register (live across
        // a call, or held through one) is kept.
        if let Insn::Movea { dst, .. } = s.out[k] {
            if call_ptrs.contains(&o) && dst < 2 {
                if !parkable_pointer_local(f, o) || !a0_free.contains(&o) {
                    // Best effort (not byte-identical): the local kept in
                    // the register allocation gave it, its copy from A0
                    // kept (bead domain-pascal-yqf6).
                    best_effort(
                        span,
                        "a pointer local assigned from a call that no call follows, assigned \
                         more than once, inside a statement, read other than dereferenced, or \
                         with A0 written before its last use (A0 or A1 in the image; not \
                         settled) is",
                    )?;
                    continue;
                }
                if !to_a0.contains(&o) {
                    to_a0.push(o);
                }
            }
        }
    }
    if !to_a0.is_empty() {
        return Ok(Selected::InA0(to_a0));
    }
    for p in &s.parked {
        // The image's D0 sites all have D0 and A0; where D0 is busy it
        // has A1 instead (0xE4D7FC: D0 and D1 hold other values over the
        // local's range), which is not modelled.
        let (Some((_, d_at)), Some((_, a_at))) = (p.d, p.home) else {
            return Err(unsupported(
                f.span,
                "a local assigned an `a0_return` result, held in D0 and never dereferenced, is",
            ));
        };
        let in_d0 = matches!(
            &s.out[d_at],
            Insn::Move {
                dst: Ea::Reg(Reg::D(0)),
                ..
            }
        );
        let in_a0 = matches!(
            &s.out[a_at],
            Insn::Movea {
                src: Ea::Reg(Reg::D(0)),
                dst: 0,
                ..
            }
        );
        let callee_saved = matches!(
            &s.out[a_at],
            Insn::Movea {
                src: Ea::Reg(Reg::D(0)),
                dst: 2..,
                ..
            }
        );
        if !(in_d0 && (in_a0 || callee_saved)) {
            best_effort(
                f.span,
                "a local assigned an `a0_return` result held in D0, where D0 or A0 is busy \
                 (A1 in the image, 0xE4D7FC; not settled) is",
            )?;
        }
    }
    if let Some(Insn::Movea {
        src: Ea::Reg(Reg::A(a)),
        ..
    }) = web_a_move.filter(|_| !spilled).map(|k| &s.out[k])
    {
        // A pointer result variable that no call follows: of the 16
        // register-held ones (`tools/resultsurvey.py pointer`), the 12 in
        // A2 and the one in A3 all have a call after their first
        // assignment (codegen-patterns 3, "Pointer results";
        // DISK_$GET_BLOCK 0xE3BBBC); the one that none follows is in D0
        // (0xE6C21A: `move.l
        // A0,D0` after DISK_$GET_BLOCK at 0xE6C244, `clr.l D0` on another
        // path, `movea.l D0,A0` at 0xE6C2AA), others in their frame slot
        // (TTY_$I_GET_DESC 0xE667BA, the NET_ module-local 0xE5A188):
        // never in A1, which the allocator gives it when it is assigned a
        // call's A0 (R2 keeps it out of A0) or A0 is busy (bead
        // domain-pascal-500).  A0 itself (only memory loads assigned, no
        // call after) is kept as before.
        if *a == 1 {
            // Best effort (not byte-identical): held in A1 as allocated,
            // which no call clobbers before the epilogue's `movea.l A1,A0`
            // (bead domain-pascal-ogf8).
            best_effort(
                f.span,
                "a pointer result variable held in a register that no call follows (D0 at \
                 0xE6C21A, the frame elsewhere; not settled) is",
            )?;
        }
    }
    // The `suba.l`s keep their order (each in its own statement and run,
    // [`crate::sched`]), so the j-th in the scheduled body is the j-th
    // selected: their spans, for the check after scheduling.
    let mut subas: Vec<(usize, Span)> = s
        .nil_results
        .iter()
        .chain(s.nil_locals.iter())
        .filter(|&&(k, _)| matches!(s.out[k], Insn::SubaSelf(_)))
        .copied()
        .collect();
    subas.sort_by_key(|&(k, _)| k);
    let suba_spans: Vec<Span> = subas.into_iter().map(|(_, span)| span).collect();
    let nil_results: &[(usize, Span)] = if spilled { &[] } else { &s.nil_results };
    for &(k, span) in nil_results {
        // A `suba.l` that the next assignment overwrites in straight-line
        // code (`f := nil; f := x`): no site.
        if let Insn::SubaSelf(a) = s.out[k] {
            let r = Reg::A(a);
            for i in &s.out[k + 1..] {
                if matches!(
                    i,
                    Insn::Label(_)
                        | Insn::Branch { .. }
                        | Insn::Dbf { .. }
                        | Insn::TableJump { .. }
                        | Insn::Rts
                ) {
                    break;
                }
                let acc = crate::regs::access(i);
                if acc.uses.contains(&r) {
                    break;
                }
                if acc.defs.contains(&r) {
                    return Err(unsupported(
                        span,
                        "`nil` as a pointer result overwritten by the next assignment before \
                         any path or use (no site; codegen-patterns 3, \"`nil` results\") is",
                    ));
                }
            }
        }
        // The last statement's `movea.l #0` is into A0 itself (TIME_$RTE_INT
        // 0xE163D6), never moved.
        if matches!(s.out[k], Insn::Movea { src: Ea::Imm(0), dst, .. } if dst != 0) {
            return Err(unsupported(
                span,
                "a last-statement `nil` result the allocator would not put in A0 is",
            ));
        }
    }
    // After the checks above, whose refusals are the more basic ones (a
    // pointer local in A1 writes A1 before a slot load, TTY_$K_*).
    check_late_slot_loads(&s.out, &late, &passed, exit, &holds)?;
    // A result computed in D0 already is not moved (0xE148E0 moves it
    // only because the `sne` left it in D1).
    let keep: Vec<bool> = s
        .out
        .iter()
        .enumerate()
        .map(|(k, i)| {
            !(s.result_moves.contains(&k)
                && (matches!(i, Insn::Move { src: Ea::Reg(a), dst: Ea::Reg(b), .. } if a == b)
                    || matches!(i, Insn::Movea { src: Ea::Reg(Reg::A(a)), dst, .. } if a == dst)))
                && !matches!(i, Insn::Label(l) if !used.contains(l))
                && !dropped.contains(&k)
        })
        .collect();
    // The units in the kept instructions' indices.  In a spilled body,
    // each instruction's reloads go before it and its stores after it
    // ([`crate::spill`]), and a unit starts with its first instruction's
    // reloads.
    let mut new_index = Vec::with_capacity(keep.len() + 1);
    let mut group_start = Vec::with_capacity(keep.len() + 1);
    let mut n = 0;
    for (j, &k) in keep.iter().enumerate() {
        group_start.push(n);
        if let Some((before, _)) = &spills {
            n += before[j].len();
        }
        new_index.push(n);
        n += usize::from(k);
        if let Some((_, after)) = &spills {
            n += after[j].len();
        }
    }
    new_index.push(n);
    group_start.push(n);
    let units: Vec<crate::sched::Unit> = s
        .units
        .iter()
        .map(|&(a, b)| (group_start[a], group_start[b]))
        .filter(|(a, b)| b - a > 1)
        .collect();
    let mut volatile_insns: Vec<usize> = volatile_insns.iter().map(|&k| new_index[k]).collect();
    // The last instruction before the first statement
    // ([`pad_above_entry_load`]).
    let entry_tail = s.entry_tail.filter(|&k| keep[k]).map(|k| new_index[k]);
    let mut next_label = s.next_label;
    let mut out: Vec<Insn> = match spills.take() {
        None => s
            .out
            .into_iter()
            .zip(keep)
            .filter(|(_, k)| *k)
            .map(|(i, _)| i)
            .collect(),
        Some((before, after)) => s
            .out
            .into_iter()
            .zip(keep)
            .zip(before.into_iter().zip(after))
            .flat_map(|((i, k), (b, a))| b.into_iter().chain(k.then_some(i)).chain(a))
            .collect(),
    };
    let entry_tail: Option<Insn> = entry_tail.map(|k| out[k].clone());
    // A parked local's `movea.l D0,An` selected before an `if` whose two
    // parts dereference it moves down to the condition's branch (bead
    // domain-pascal-dgb; TTY_$K_SET_INPUT_FLAG 0xE67684..0xE6768C
    // `movea.l (0x10,A6),A1; movea.l D0,A0; tst.b (A1); bpl.b`, and
    // TTY_$K_SET_OUTPUT_FLAG, TTY_$K_SET_ECHO_FLAG; TTY_$K_ENABLE_FUNC
    // 0xE675DC with A2).  It is selected first so that the allocator
    // keeps the condition's registers off An (A1 above), and then sits
    // just before the branch, where the scheduler lists it after the
    // condition's first load (12.4 R11).  Only the condition's own
    // instructions lie between, and none of them may touch D0 or An.
    // Not in a spilled body: the move stays where it was selected (correct;
    // the spills' reloads may lie between).
    let hoists: &[(usize, usize, Span)] = if spilled { &[] } else { &s.hoists };
    for &(m, b, span) in hoists {
        let (m, b) = (new_index[m], new_index[b]);
        let Insn::Movea {
            src: Ea::Reg(src),
            dst,
            ..
        } = out[m].clone()
        else {
            unreachable!("a hoist is a movea.l")
        };
        let touched = out[m + 1..b].iter().any(|i| {
            let a = crate::regs::access(i);
            matches!(
                i,
                Insn::Label(_) | Insn::Branch { .. } | Insn::Jsr(_) | Insn::Bsr { .. }
            ) || a.defs.contains(&src)
                || a.defs.contains(&Reg::A(dst))
                || a.uses.contains(&Reg::A(dst))
        });
        let split = units.iter().any(|&(u0, u1)| u0 < b && m < u1);
        if touched || split || !matches!(out[b], Insn::Branch { .. }) {
            return Err(unsupported(
                span,
                "an `if` whose condition uses the register of a pointer local held in D0 is",
            ));
        }
        let mv = out.remove(m);
        out.insert(b - 1, mv);
        for k in volatile_insns.iter_mut() {
            if *k == m {
                *k = b - 1;
            } else if m < *k && *k < b {
                *k -= 1;
            }
        }
    }
    // The instructions that reference volatile objects, for
    // [`thread_past_tests`] after scheduling (by value: equal instructions
    // count as volatile too).
    let volatile_set: Vec<Insn> = volatile_insns.iter().map(|&k| out[k].clone()).collect();
    // Phase 1c: the order inside basic blocks (`sched.rs`).
    crate::sched::schedule(&mut out, &units, &volatile_insns, sched);
    if let Some(last) = &entry_tail {
        pad_above_entry_load(&mut out, last);
    }
    if !suba_spans.is_empty() {
        // A `nil` right before a call's pad: the image has it after the
        // pad (0xE09D42 `subq.l #2,SP; suba.l A2,A2; move.w #18,-(SP)`,
        // EC2_$ALLOCATE_EC1 0xE42A6A; 11 of the 12 register constants
        // right before a padded call's first push in straight-line code
        // are after the pad, `clr.b D2` at 0xE04B14, 0xE0728A, ...), where
        // the selector's order, kept by R11 (12.4), has it first (bead
        // domain-pascal-ncac).
        let pad = |i: &Insn| {
            matches!(
                i,
                Insn::Subq {
                    size: Size::L,
                    value: 2,
                    dst: Ea::Reg(Reg::A(7)),
                }
            )
        };
        let before_pad = out
            .iter()
            .filter(|i| matches!(i, Insn::SubaSelf(_)))
            .zip(suba_spans.iter())
            .zip(out.windows(2).filter(|w| matches!(w[0], Insn::SubaSelf(_))))
            .find(|(_, w)| pad(&w[1]))
            .map(|((_, span), _)| *span);
        if let Some(span) = before_pad {
            best_effort(
                span,
                "`nil` into an address register right before a call's pad (after the pad in \
                 the image, 0xE09D44, 0xE42A6C; bead domain-pascal-ncac) is",
            )?;
        }
    }
    for (lea, user, span) in &once_pairs {
        if !out.windows(2).any(|w| w[0] == *lea && w[1] == *user) {
            best_effort(*span, ONCE_LEA_SCHEDULED)?;
        }
    }
    for (lea, count, span) in &elem_count_pairs {
        // The `lea`, then the count later in the same straight-line run.
        let after = out.iter().enumerate().any(|(i, x)| {
            x == lea
                && out[i + 1..]
                    .iter()
                    .take_while(|y| {
                        !matches!(y, Insn::Label(_) | Insn::Branch { .. } | Insn::Dbf { .. })
                    })
                    .any(|y| y == count)
        });
        if !after {
            best_effort(*span, ELEMENT_COUNT_SCHEDULED)?;
        }
    }
    for (movea, pea, span) in &elem_value_triples {
        // `addr` of another unit's element by value: no push between its
        // base's load and its `pea` ([`ELEM_BASE_ABOVE_PUSH`]).
        let ok = out.iter().enumerate().any(|(i, x)| {
            x == movea
                && out[i + 1..]
                    .iter()
                    .position(|y| y == pea)
                    .is_some_and(|j| !out[i + 1..i + 1 + j].iter().any(is_push))
        });
        if !ok {
            best_effort(*span, ELEM_BASE_ABOVE_PUSH)?;
        }
    }
    for (t, span) in &zext_triples {
        // A zero-extended `.l` index of another unit's array: the base
        // between the `clr.l` and the copy, with nothing else between
        // them (44 of 44 such sites of a word held in a register; apart,
        // 3 between and 4 after: `tools/arithsurvey.py wordidx`,
        // codegen-patterns 5.2, "Word indices used as `.l`").
        if !out.windows(3).any(|w| w == &t[..]) {
            best_effort(*span, ZEXT_BASE_SCHEDULED)?;
        }
    }
    thread_past_tests(&mut out, &mut next_label, &volatile_set);
    copy_repeated_constants(&mut out);
    Ok(Selected::Body(
        Body {
            insns: out,
            saves: saves.union(s.clobbered),
            spill: spill_bytes,
        },
        s.cse_hits,
    ))
}

/// A `bra` right after a store goes past a test of the stored object at
/// its target (codegen-patterns 7.1, "A branch past the test of a store";
/// ../source pascal-translation-notes 374): a `move.<s>` or `clr.<s>`
/// into memory sets N and Z from the value and clears V and C, as `tst.<s>`
/// of it would, so the `bra` lands on what follows the `tst`.  After a
/// `clr`, whose flags are known, a conditional branch there that cannot
/// be taken is passed over too.  `tools/resultsurvey.py storebra`, the
/// 51 `bra`s right after a `move`/`clr` into memory whose target is at a
/// `tst` of that object, right after it, or right after the branch that
/// follows it:
/// - 34 land after the `tst` (io_$check_unit 0xE1A4BE `move.l
///   #0x100008,(A0); bra.s` to the `seq D0` past `tst.l (A0)`; IO_$ACQUIRE
///   0xE1A5FE to the `bne.w` past `tst.l (A4)`; 0xE17F46 `bne`, 0xE4B4B2
///   `beq`, 0xE38482 from a register);
/// - 8 after a `clr` pass the `tst` and a `bne`/`bmi` that cannot be
///   taken (IO_$ACQUIRE 0xE1A566 `clr.l (A4); bra.b 0xE1A576` past `tst.l
///   (A4); bne.w`; XNS_IDP_$OS_OPEN 0xE17FC2; DXM_$ADD_CALLBACK 0xE1709A
///   `clr.b (-36,A6)` past `tst.b; bmi`); 4 more pass a branch whose
///   outcome the store does not give (0xE4BABA, 0xE4BB3E: a label after
///   the test, not this rule);
/// - 5 land on the `tst`: a `bra` into a loop's test at the bottom
///   (FILE_$PRIV_LOCK 0xE5F26C, `bgt.w` back), a `clr` before a `beq` that
///   is always taken (0xE3E446), and 0xE5F134, ASKNODE_$SERVER 0xE65B76,
///   0xE6133A (not explained).
/// So not done for a test that branches back, nor after a `clr` before a
/// branch that is always taken, nor for volatile objects (`volatile`, as
/// selected).  A `st`/`sf` sets no flags (0xE4DF9C lands on the `tst`).
fn thread_past_tests(out: &mut Vec<Insn>, next_label: &mut u32, volatile: &[Insn]) {
    use std::collections::HashMap;
    let at: HashMap<u32, usize> = out
        .iter()
        .enumerate()
        .filter_map(|(i, x)| match x {
            Insn::Label(l) => Some((*l, i)),
            _ => None,
        })
        .collect();
    // (index of the `bra`, position its new target is before).
    let mut moves: Vec<(usize, usize)> = Vec::new();
    for i in 1..out.len() {
        let Insn::Branch {
            cond: Cond::T,
            label,
            ..
        } = &out[i]
        else {
            continue;
        };
        let (size, ea, cleared) = match &out[i - 1] {
            Insn::Move { size, dst, .. } => (*size, dst, false),
            Insn::Clr { size, dst } => (*size, dst, true),
            _ => continue,
        };
        if matches!(
            ea,
            Ea::Reg(_) | Ea::PreDec(_) | Ea::PostInc(_) | Ea::Imm(_) | Ea::ImmSym(_)
        ) || volatile.contains(&out[i - 1])
        {
            continue;
        }
        let Some(&p) = at.get(label) else { continue };
        let mut q = p;
        while matches!(out.get(q), Some(Insn::Label(_))) {
            q += 1;
        }
        match out.get(q) {
            Some(Insn::Tst { size: s, dst }) if *s == size && dst == ea => {}
            _ => continue,
        }
        if volatile.contains(&out[q]) {
            continue;
        }
        let mut t = q + 1;
        match out.get(t) {
            Some(Insn::Branch { back: true, .. }) => continue,
            // After `clr` (Z set, N, V, C clear): past a branch that cannot
            // be taken; at the `tst` before one that always is (0xE3E446).
            Some(Insn::Branch { cond, .. }) if cleared => match cond {
                Cond::Ne | Cond::Mi | Cond::Gt | Cond::Lt | Cond::Hi | Cond::Cs => t += 1,
                _ => continue,
            },
            _ => {}
        }
        moves.push((i, t));
    }
    if moves.is_empty() {
        return;
    }
    // A label already there, or a new one, per target.
    let mut new_at: Vec<(usize, u32)> = Vec::new();
    for &(i, t) in &moves {
        let l = match out.get(t) {
            Some(Insn::Label(l)) => *l,
            _ => match new_at.iter().find(|(p, _)| *p == t) {
                Some(&(_, l)) => l,
                None => {
                    let l = *next_label;
                    *next_label += 1;
                    new_at.push((t, l));
                    l
                }
            },
        };
        if let Insn::Branch { label, .. } = &mut out[i] {
            *label = l;
        }
    }
    new_at.sort_by(|a, b| b.0.cmp(&a.0));
    for (t, l) in new_at {
        out.insert(t, Insn::Label(l));
    }
}

/// Branch threading (codegen-patterns 7.1, "Branch threading"; bead
/// domain-pascal-o6p).  Compiled code has no branch to a `bra`
/// (`tools/threadsurvey.py tobra`: none of the `b<cc>`, `bra`, `dbf` or
/// `case` table entries of 0xE00800..0xE88834), and 845 forward branches
/// go past a `bra` to that `bra`'s own target, the outer join or the
/// epilogue (`thread`: TTY_$K_SET_FLAG 0xE6746A `beq.b 0xE67482` past the
/// `bra.b 0xE67482` at 0xE6747A).  So a branch to a label that a `bra`
/// follows takes the `bra`'s target, transitively.  A `bra` that nothing
/// reaches after that (the instruction before it an unconditional `bra`)
/// is dropped: no such `bra` is in the image (`dead`: none), and a
/// `while` whose opening `bra` follows one is entered by the threaded
/// branch to its test alone (TTY_$K_GET 0xE1C44A `bpl.w 0xE1C4FC`, the
/// head 0xE1C4D6 right after the `then` part's `bra.s` at 0xE1C4D4;
/// TTY_$K_PUT 0xE67C0E), its head still aligned in aligning code (the module-local
/// 0xE4AFA8: `bne.b 0xE4B0FC` to the test, `bra.s` at 0xE4B0F4, the
/// filler at 0xE4B0F6, the head 0xE4B0F8).  The sizes follow from the
/// threaded layout (`size_branches`): 263 of the threaded branches are
/// `.w` though a `.s` would have reached the `bra`.
///
/// At the bottom of a loop with no test (codegen-patterns 7.2, "Loops
/// with no test"; bead domain-pascal-pkle), a conditional branch over the
/// `bra` back to the head becomes the negated branch to the head, and a
/// `bra` that the dropping of that `bra` leaves going to the next
/// instruction is dropped too (compiled code has neither).
///
/// The dropped `bra` becomes a fresh label that nothing names, so the
/// indices into `out` stay valid; the unused labels go later.  Refused:
/// a `dbf` or a `case` table entry whose target a `bra` follows (an arm
/// of only `return`; no table entry in the image goes to the epilogue
/// unless its default does; bead domain-pascal-r4yn), a cycle of `bra`s,
/// any other branch that threading leaves pointing at the next
/// instruction (not seen), and a loop head that falls into a `bra` (a `repeat` before a
/// `while`; bead domain-pascal-tfae).  An `exit`, `next` or `goto` whose
/// `bra` is dropped leaves its entry in `loop_jumps` / `goto_jumps`
/// pointing at a label; [`select_body_with`] skips those.
fn thread_branches(
    out: &mut [Insn],
    next_label: &mut u32,
    before_bra: &[(u32, Span)],
    span: Span,
) -> Res<()> {
    use std::collections::HashMap;
    let span_of = |l: u32| {
        before_bra
            .iter()
            .find(|(m, _)| *m == l)
            .map_or(span, |&(_, s)| s)
    };
    let refused = |l: u32, what: &str| {
        unsupported(
            span_of(l),
            format!(
                "{what} whose target a `bra` follows (compiled code has no branch to a `bra`; \
                 only branches are seen threaded, codegen-patterns 7.1) is"
            ),
        )
    };
    // The `bra` right after each label (other labels between).
    let mut succ: HashMap<u32, u32> = HashMap::new();
    let mut pos: HashMap<u32, usize> = HashMap::new();
    for (k, i) in out.iter().enumerate() {
        if let Insn::Label(l) = i {
            pos.insert(*l, k);
            let next = out[k + 1..].iter().find(|i| !matches!(i, Insn::Label(_)));
            if let Some(Insn::Branch {
                cond: Cond::T,
                label,
                ..
            }) = next
            {
                succ.insert(*l, *label);
            }
        }
    }
    let resolve = |l: u32| -> Option<u32> {
        let mut t = l;
        for _ in 0..=succ.len() {
            match succ.get(&t) {
                Some(&m) => t = m,
                None => return Some(t),
            }
        }
        None
    };
    for (k, i) in out.iter_mut().enumerate() {
        match i {
            Insn::Branch { label, back, .. } if succ.contains_key(label) => {
                let Some(t) = resolve(*label) else {
                    return Err(refused(*label, "a cycle of `bra`s (a branch)"));
                };
                *label = t;
                *back = pos[&t] < k;
            }
            Insn::Dbf { label, .. } if succ.contains_key(label) => {
                // Best effort (not byte-identical): the `dbf` left on its
                // label, whose `bra` stays (bead domain-pascal-ogf8).
                best_effort(
                    span_of(*label),
                    "a `dbf` whose target a `bra` follows (compiled code has no branch to a \
                     `bra`; only branches are seen threaded, codegen-patterns 7.1) is",
                )?;
            }
            Insn::TableEntry { target, .. } if succ.contains_key(target) => {
                // Best effort (not byte-identical): the entry left on the
                // arm, whose `bra` stays (no table entry in the image goes
                // to the epilogue unless its default does; bead
                // domain-pascal-r4yn).
                best_effort(
                    span_of(*target),
                    "a `case` table entry whose target a `bra` follows (compiled code has no \
                     branch to a `bra`; only branches are seen threaded, codegen-patterns 7.1) is",
                )?;
            }
            _ => {}
        }
    }
    // The labels still named after threading.
    let used: std::collections::HashSet<u32> = out
        .iter()
        .flat_map(|i| match i {
            Insn::Branch { label, .. } | Insn::Dbf { label, .. } => vec![*label],
            Insn::TableIndex { table, .. } => vec![*table],
            Insn::TableEntry { target, .. } => vec![*target],
            _ => vec![],
        })
        .collect();
    // A `bra` after an unconditional `bra`, with no named label between
    // (a loop head's alignment may be: the head of a `while` whose body
    // starts with a `while`, its back edge threaded to the inner test).
    let mut dead = Vec::new();
    for k in 0..out.len() {
        if !matches!(out[k], Insn::Branch { cond: Cond::T, .. }) {
            continue;
        }
        let prev = out[..k].iter().rev().find(|i| {
            !matches!(i, Insn::Label(l) if !used.contains(l)) && !matches!(i, Insn::Align4)
        });
        if matches!(prev, Some(Insn::Branch { cond: Cond::T, .. })) {
            dead.push(k);
        }
    }
    // The dropped `bra`s that went back to a loop head: the bottom of a
    // loop with no test (`repeat ... until false`) after a body that ends
    // in a jump.
    let dead_back: Vec<usize> = dead
        .iter()
        .copied()
        .filter(|&k| matches!(out[k], Insn::Branch { back: true, .. }))
        .collect();
    for &k in &dead {
        out[k] = Insn::Label(*next_label);
        *next_label += 1;
    }
    // A conditional branch over a `bra` back to a loop head (the bottom of
    // a loop with no test, after an `if c then exit` that ends its body)
    // is the branch on the negated condition to the head, with no `bra`:
    // compiled code has no conditional branch over a `bra` (codegen-
    // patterns 7.1; `tools/threadsurvey.py over`: none), and PKT_$SAR_
    // INTERNET's wait 0xE72152 `cmp.w D4w,D2w; bne.w 0xE71FE8` falls into
    // the code after the loop (codegen-patterns 7.2).
    for k in 0..out.len() {
        let Insn::Branch {
            cond,
            label: over,
            short,
            ..
        } = out[k]
        else {
            continue;
        };
        if cond == Cond::T {
            continue;
        }
        let Some(j) =
            (k + 1..out.len()).find(|&j| !matches!(out[j], Insn::Label(l) if !used.contains(&l)))
        else {
            continue;
        };
        let Insn::Branch {
            cond: Cond::T,
            label: head,
            back: true,
            ..
        } = out[j]
        else {
            continue;
        };
        let lands = out[j + 1..]
            .iter()
            .take_while(|i| matches!(i, Insn::Label(_) | Insn::Align4))
            .any(|i| matches!(i, Insn::Label(l) if *l == over));
        if !lands {
            continue;
        }
        out[k] = Insn::Branch {
            cond: cond.negate(),
            label: head,
            short,
            back: true,
        };
        out[j] = Insn::Label(*next_label);
        *next_label += 1;
    }
    // The dropped `bra` of a `while` that starts a `while`'s body leaves
    // the two heads' alignments together: one is enough (the outer head
    // is no longer a branch target).
    for k in 0..out.len() {
        if matches!(out[k], Insn::Align4)
            && matches!(
                out[k + 1..]
                    .iter()
                    .find(|i| !matches!(i, Insn::Label(l) if !used.contains(l))),
                Some(Insn::Align4)
            )
        {
            out[k] = Insn::Label(*next_label);
            *next_label += 1;
        }
    }
    // A branch now to the next instruction (the labels and a loop head's
    // alignment between): not seen.
    for k in 0..out.len() {
        let Insn::Branch { cond, label, .. } = out[k] else {
            continue;
        };
        let to = out[k + 1..]
            .iter()
            .take_while(|i| matches!(i, Insn::Label(_) | Insn::Align4))
            .position(|i| matches!(i, Insn::Label(l) if *l == label))
            .map(|n| k + 1 + n);
        // A `bra` to the next instruction once the `bra` back to the head
        // of a loop with no test is dropped: an `exit` or `return` ending
        // the body (MSG_$SARI's wait, whose last `case` arm ends in `exit`:
        // 0xE59F76..0xE59F98, then the code after the loop at 0xE59F9E,
        // with no `bra` between).  Compiled code has no branch to the next
        // instruction (codegen-patterns 7.2; `tools/threadsurvey.py next`:
        // none).
        if let Some(to) = to {
            if cond == Cond::T && dead_back.iter().any(|&d| k < d && d < to) {
                out[k] = Insn::Label(*next_label);
                *next_label += 1;
                continue;
            }
        }
        if to.is_some() && !dead.is_empty() {
            best_effort(
                span,
                "a branch that would go to the next instruction once a `bra` no longer reached \
                 is dropped (not seen, codegen-patterns 7.1) is",
            )?;
        }
    }
    // A loop head that a `bra` still follows (a `repeat`, or a backward
    // `goto`'s label, before a `while`: the back edge goes to the inner
    // test, and the head, reached by falling into it, is a branch target
    // no longer).  Compiled code has no 0x2048 filler before a `bra` that
    // falls through to it, and a head entered so is not seen in aligning
    // code: whether the original still aligns it is not known (bead
    // domain-pascal-tfae).
    for k in 0..out.len() {
        if !matches!(out[k], Insn::Align4) {
            continue;
        }
        let rest = || {
            out[k + 1..]
                .iter()
                .skip_while(|i| matches!(i, Insn::Label(_) | Insn::Align4))
        };
        let head = out[k + 1..].iter().find_map(|i| match i {
            Insn::Label(l) => Some(*l),
            _ => None,
        });
        let next = rest().next();
        if matches!(next, Some(Insn::Branch { cond: Cond::T, .. })) {
            best_effort(
                head.map_or(span, span_of),
                "a `repeat` or a backward `goto`'s label right before a `while` (the back edge \
                 goes to the `while`'s test; whether the head, falling into the opening `bra`, \
                 stays aligned is not seen, codegen-patterns 7.1) is",
            )?;
        }
    }
    Ok(())
}

/// The memory operands instruction `i` reads or writes (not those whose
/// address only it takes: `pea`, `lea`, `jsr`).
fn memory_operands(i: &Insn) -> Vec<&Ea> {
    let v: Vec<&Ea> = match i {
        Insn::Move { src, dst, .. } => vec![src, dst],
        Insn::Movea { src, .. }
        | Insn::Cmp { src, .. }
        | Insn::Cmpa { src, .. }
        | Insn::Alu { src, .. }
        | Insn::Mul { src, .. }
        | Insn::Div { src, .. } => vec![src],
        Insn::Addq { dst, .. }
        | Insn::Subq { dst, .. }
        | Insn::Clr { dst, .. }
        | Insn::Btst { dst, .. }
        | Insn::Scc { dst, .. }
        | Insn::Tst { dst, .. }
        | Insn::Cmpi { dst, .. }
        | Insn::AluImm { dst, .. }
        | Insn::Unary { dst, .. }
        | Insn::BtstImm { dst, .. }
        | Insn::BitImm { dst, .. }
        | Insn::Bit { dst, .. }
        | Insn::AluToMem { dst, .. } => vec![dst],
        _ => vec![],
    };
    v.into_iter()
        .filter(|e| !matches!(e, Ea::Reg(_) | Ea::Imm(_) | Ea::ImmSym(_)))
        .collect()
}

/// The memory operand instruction `i` reads before it writes it: the
/// read-modify-write instructions, and `clr` and `s<cc>`, which on the
/// MC68000/68010 read their operand before writing it (MC68000 PRM).
fn read_modify_write_operand(i: &Insn) -> Option<&Ea> {
    let dst = match i {
        Insn::Addq { dst, .. }
        | Insn::Subq { dst, .. }
        | Insn::Clr { dst, .. }
        | Insn::Scc { dst, .. }
        | Insn::AluImm { dst, .. }
        | Insn::Unary { dst, .. }
        | Insn::BitImm { dst, .. }
        | Insn::Bit { dst, .. }
        | Insn::AluToMem { dst, .. } => dst,
        _ => return None,
    };
    (!matches!(dst, Ea::Reg(_))).then_some(dst)
}

/// The indices in `out` of the instructions that reference a volatile
/// object (`eas`, the operands [`Selector::ea_of`] gave for
/// [`Addr::Volatile`] addresses; virtual registers name one value each,
/// so an operand names one object).  A `clr` or `s<cc>` on a device
/// object is refused (ref 3.15.3 p. 3-57, "the compiler [avoids] using
/// instructions that do unnecessary reads"; codegen-patterns 5.5, 13):
/// they read an operand they do not need, the selector does not choose
/// one for a device ([`Selector::store`]), so one here comes from a form
/// it has no device variant of.  The other read-modify-write
/// instructions need the old value, and are allowed in the statements
/// that read it ([`Selector::check_device_updates`]).
fn volatile_references(out: &[Insn], eas: &[(Ea, Access)], span: Span) -> Res<Vec<usize>> {
    let mut v = Vec::new();
    for (k, i) in out.iter().enumerate() {
        if let Some(d) = read_modify_write_operand(i)
            .filter(|_| matches!(i, Insn::Clr { .. } | Insn::Scc { .. }))
        {
            if eas.iter().any(|(e, a)| a.device && e == d) {
                return Err(unsupported(
                    span,
                    "a read-modify-write instruction on a device object (ref 3.15.3) is",
                ));
            }
        }
        if memory_operands(i)
            .iter()
            .any(|m| eas.iter().any(|(e, _)| e == *m))
        {
            v.push(k);
        }
    }
    Ok(v)
}

/// The values to hold live through a call (codegen-patterns 12.4 R4(c)),
/// as `(index of the jsr/bsr, register)` for [`allocate`].
///
/// A value defined before a call statement whose last use is in that
/// statement's arguments:
///
/// - in a body without branches it is held through the call, so it takes
///   a callee-saved register: PROC1_$SET_ASID 0xE148FE D2 (`move.w
///   D2,-(SP)` at 0xE1490E); TTY_$I_FLUSH_OUTPUT 0xE1B80C A2,
///   TTY_$I_OUTPUT_BUFFER_DRAINED 0xE1B39A A2, module-local 0xE1D592 at
///   0xE1D598 A2, SIO_$I_INIT 0xE67E64 A2.  These are
///   all five such parameter loads in the image's routines without
///   branches where liveness alone leaves a scratch register free
///   (`tools/regalloc.py callargs`, `callparams`);
/// - in a body with branches, a parameter loaded at entry (`params`) is
///   held too, wherever the call lies (bead domain-pascal-9j1z;
///   `tools/regalloc.py callparams`, the parameters loaded once before
///   the routine's first branch, branch target or call, whose last use on
///   some path pushes an argument of a call, with a scratch register free
///   by liveness): before the first branch, 2 of 2 callee-saved
///   (VOLX_$GET_INFO 0xE6B5D4 A3, 0xE6B5D8 A4); in a conditional part, 26
///   of 27 (AREA_$ASSOC 0xE096B0 D2, `move.w D2,-(SP)` at 0xE096D2;
///   XPD_$GET_FP_INT 0xE5C560 A2, a call in each part); after a join
///   inside one, 5 of 5 (SOCK_$PUT_INT 0xE161A2 A2, `pea (A2)` at
///   0xE161E4; the nested 0xE1CC10 of KBD_$RCV keeps `kbd` in A2,
///   `move.l (0x48,A2),-(SP)` at 0xE1CC52); whether the
///   value is also used on another path (10 of 10) or passed to several
///   calls (7 of 7) does not matter, nor does the class (A 29 of 29, D 4
///   of 5).  Refused:
///   - the one other site's kind, a pointer parameter held in a data
///     register (`data_ptrs`): EC2_$ADVANCE 0xE42CB8 pushes D0, a scratch
///     register, `move.l D0,-(SP)` at 0xE42CDA, the only such site;
///   - a call on every path after a join: its 4 sites are all
///     callee-saved, but at each no scratch register is free by
///     liveness, so they do not show whether the value is held;
/// - other values, by kind (codegen-patterns 12.4 R4(c), "Other values,
///   with branches"; bead domain-pascal-ig8d; `tools/regalloc.py
///   callothers`):
///   - `with_elems`, a `with` record that is an array element: held, as
///     21 of the 23 such element addresses are (EC2_$RELEASE_EC1 0xE42B96
///     A2, `pea (A2)` at 0xE42BB0 in an `else` part; MMAP_$INSTALL_PAGES
///     0xE0CE28; IO_$DISABLE_DEVICE 0xE1A820, the call register loaded
///     from it; the two others are not held in a register: FLP_DO_IO
///     0xE3DDEE keeps the address in D3, AREA_$COPY 0xE09052 in its frame
///     slot).  Refused where no site shows it: the call before the first
///     branch, the call on every path after a join, last uses in several
///     calls' arguments or outside a call's arguments on another path
///     ([`last_use_calls`]);
///   - the other `withs`, a record reached through a loaded pointer:
///     refused (such loads are held at some sites, not at others:
///     SOCK_$PUT_INT 0xE161C2 A3, SIO6509_$RCV 0xE1D552 A0);
///   - `locals`, register-held locals: refused (DTTY_$TSTART 0xE1D6F8
///     keeps `current` in D0, MSG_$SEND_HW 0xE59B92 `port` in D2; NET_$OPEN
///     calls its routine pointer local through A0 kept from the call that
///     returned it, 0xE5A1F4, and stores it to its slot);
///   - any other computed value: refused.
///
/// A value already live across an earlier call (so in a callee-saved
/// register by R3) is held with branches too: CAL_$SHUTDOWN 0xE3E6E4
/// keeps `status` in A2 across DBUF_$GET_BLOCK and passes it last to
/// DBUF_$SET_BUFF (`pea (A2)` at 0xE3E72A); `tools/regalloc.py callargs`
/// counts only values that cross no call.
///
/// `ptrs`: the registers of pointer locals assigned from calls
/// ([`call_pointer_locals`]), held through such a call with branches too:
/// of the 108 `movea.l A0,An` copies of a call's result, the 13 whose
/// register is next read only inside a later call's arguments, all in
/// bodies with branches, are all in callee-saved registers (AST_
/// module-local 0xE070CA `movea.l A0,A3`, `pea (A3)` at 0xE070DC;
/// VTOC_$ALLOCATE 0xE38BB6; KBD_$SET_KBD_TYPE 0xE7253E A2, `pea (A2)`
/// at 0xE72550), against none in A1 or D0/D1 (bead domain-pascal-500,
/// ad-hoc script over `tools/resultsurvey.py`'s `a0_reads`).
///
/// `link`: the register of a nested routine's static link (codegen-patterns
/// 6), loaded at entry like a parameter; whether the original held it
/// through a call whose arguments use it last (reaching the enclosing
/// frame, or passing it on to a sibling) is not seen either.
///
/// `blocks`: the registers holding another data section's block
/// ([`Selector::other_base`]): never held, loaded again after the call.
fn held_through_calls(
    out: &[Insn],
    calls: &[(usize, usize, Span)],
    exit: &[Reg],
    kinds: HeldKinds,
) -> Res<Vec<(usize, Reg)>> {
    let HeldKinds {
        link,
        ptrs,
        blocks,
        params,
        data_ptrs,
        withs,
        with_elems,
        locals,
    } = kinds;
    let straight = !out
        .iter()
        .any(|i| matches!(i, Insn::Branch { .. } | Insn::Dbf { .. }));
    let live_out = crate::regs::liveness(out, exit, &[]);
    let mut holds = Vec::new();
    for &(start, call, span) in calls {
        let defined_before: Vec<Reg> = out[..start]
            .iter()
            .flat_map(|i| crate::regs::access(i).defs)
            .filter(|&r| crate::regs::is_virtual(r))
            .collect();
        for i in &out[start..call] {
            for r in crate::regs::access(i).uses {
                if !defined_before.contains(&r)
                    || blocks.contains(&r)
                    || live_out[call].contains(&crate::regs::RegKey(r))
                    || holds.contains(&(call, r))
                {
                    continue;
                }
                if !straight && Some(r) == link {
                    best_effort(
                        span,
                        "in a body with branches, a call whose arguments are the last use of the \
                         static link (held through the call or not, codegen-patterns 6, 12.4 \
                         R4(c)) is",
                    )?;
                }
                // A value live across an earlier call is in a callee-saved
                // register whatever this call does (12.4 R3); the survey
                // of R4(c) leaves such values out (`tools/regalloc.py
                // callargs`, `crosses_call`): held, as in a body without
                // branches.
                let crossed = calls
                    .iter()
                    .any(|&(_, c, _)| c < start && live_out[c].contains(&crate::regs::RegKey(r)));
                if !straight && !ptrs.contains(&r) && !crossed {
                    if with_elems.contains(&r) {
                        // A `with` record that is an array element: held
                        // (bead domain-pascal-ig8d; 21 of 23 element
                        // addresses, `tools/regalloc.py callothers`).
                        if !after_a_branch(out, call) {
                            // The survey's one site before the first branch,
                            // FLP_DO_IO 0xE3DDEE, keeps the address in D3,
                            // across calls: no held-or-not evidence.
                            best_effort(
                                span,
                                "in a body with branches, a call before the first branch whose \
                                 arguments are the last use of a `with` record's element address \
                                 (held through the call or not: no such site, codegen-patterns \
                                 12.4 R4(c)) is",
                            )?;
                        }
                        if on_every_path(out, call) {
                            best_effort(
                                span,
                                "a call on every path after a join whose arguments are the last \
                                 use of a `with` record's element address (held through the \
                                 call or not: no such site, codegen-patterns 12.4 R4(c)) is",
                            )?;
                        }
                        match last_use_calls(out, &live_out, calls, r) {
                            Some(cs) if cs.len() == 1 => {}
                            Some(_) => {
                                best_effort(
                                    span,
                                    "in a body with branches, a `with` record's element address \
                                     whose last uses are the arguments of several calls (held \
                                     through them or not: only a site where no scratch register \
                                     is free, AST_$REMOVE_CORRUPTED_PAGE 0xE072FA; \
                                     codegen-patterns 12.4 R4(c)) is",
                                )?;
                            }
                            None => {
                                best_effort(
                                    span,
                                    "in a body with branches, a call whose arguments are the \
                                     last use of a `with` record's element address that is \
                                     also last used outside a call's arguments on another path \
                                     (held through the call or not: no such site, \
                                     codegen-patterns 12.4 R4(c)) is",
                                )?;
                            }
                        }
                    } else if withs.contains(&r) {
                        best_effort(
                            span,
                            "in a body with branches, a call whose arguments are the last use of \
                             a `with` record's address loaded as a pointer (held through the \
                             call or not: loaded pointers are held at some sites and not at \
                             others, SIO6509_$RCV 0xE1D552 A0, SOCK_$PUT_INT 0xE161C2 A3; \
                             codegen-patterns 12.4 R4(c)) is",
                        )?;
                    } else if locals.contains(&r) {
                        best_effort(
                            span,
                            "in a body with branches, a call whose arguments are the last use of \
                             a register-held local (held through the call or not: DTTY_$TSTART \
                             0xE1D6F8 keeps one in D0, MSG_$SEND_HW 0xE59B92 in D2; a routine \
                             pointer called is kept in A0 and stored, NET_$OPEN 0xE5A1F4; \
                             codegen-patterns 12.4 R4(c)) is",
                        )?;
                    } else if !params.contains(&r) {
                        best_effort(
                            span,
                            "in a body with branches, a call whose arguments are the last use of \
                             a value computed in an earlier statement (held through the call or \
                             not; codegen-patterns 12.4 R4(c)) is",
                        )?;
                    } else if data_ptrs.contains(&r) {
                        best_effort(
                            span,
                            "in a body with branches, a call whose arguments are the last use of \
                             a pointer parameter held in a data register (not held at \
                             EC2_$ADVANCE 0xE42CDA, the only site; codegen-patterns 12.4 R4(c), \
                             bead domain-pascal-b3wz) is",
                        )?;
                    } else if after_a_branch(out, call) && on_every_path(out, call) {
                        best_effort(
                            span,
                            "a call on every path after a join whose arguments are the last use \
                             of a parameter loaded at entry (held through the call or not: no \
                             site with a scratch register free, codegen-patterns 12.4 R4(c), \
                             bead domain-pascal-cs2n) is",
                        )?;
                    }
                }
                holds.push((call, r));
            }
        }
    }
    Ok(holds)
}

/// The calls (indices in `out`) whose argument instructions (`calls`: the
/// statement's first instruction up to the call) hold the last uses of
/// register `r` (an instruction reading it, after which it is dead); `None`
/// when one of them lies outside every call's arguments (codegen-patterns
/// 12.4 R4(c), the survey's "other" paths).
fn last_use_calls(
    out: &[Insn],
    live_out: &[std::collections::BTreeSet<crate::regs::RegKey>],
    calls: &[(usize, usize, Span)],
    r: Reg,
) -> Option<Vec<usize>> {
    let mut found = Vec::new();
    for (i, insn) in out.iter().enumerate() {
        if !crate::regs::access(insn).uses.contains(&r)
            || live_out[i].contains(&crate::regs::RegKey(r))
        {
            continue;
        }
        let &(_, c, _) = calls.iter().find(|&&(st, c, _)| st <= i && i <= c)?;
        if !found.contains(&c) {
            found.push(c);
        }
    }
    Some(found)
}

/// The kinds of values [`held_through_calls`] treats apart.
struct HeldKinds<'a> {
    /// The static link's register.
    link: Option<Reg>,
    /// Pointer locals assigned from calls.
    ptrs: &'a [Reg],
    /// Registers holding another data section's block.
    blocks: &'a [Reg],
    /// The parameters loaded at entry ([`Selector::entry_loads`]).
    params: &'a [Reg],
    /// Those of `params` held in a data register although pointers.
    data_ptrs: &'a [Reg],
    /// The registers of `with` records' addresses.
    withs: &'a [Reg],
    /// Those of `withs` that hold an array element's address.
    with_elems: &'a [Reg],
    /// The registers of register-held locals.
    locals: &'a [Reg],
}

/// A branch, `dbf`, `case` dispatch or branch target comes before
/// instruction `i` of `out`.
fn after_a_branch(out: &[Insn], i: usize) -> bool {
    out[..i].iter().any(|x| {
        matches!(
            x,
            Insn::Branch { .. } | Insn::Dbf { .. } | Insn::TableJump { .. } | Insn::Label(_)
        )
    })
}

/// Every path from the start of the body to its end goes through
/// instruction `i` of `out`.
fn on_every_path(out: &[Insn], i: usize) -> bool {
    if out.is_empty() {
        return true;
    }
    let succ = crate::regs::successors(out);
    let mut seen = vec![false; out.len()];
    let mut work = vec![0usize];
    while let Some(j) = work.pop() {
        if j == i || seen[j] {
            continue;
        }
        seen[j] = true;
        if matches!(out[j], Insn::Rts) {
            return false;
        }
        for s in &succ[j] {
            match s {
                Some(k) => work.push(*k),
                None => return false,
            }
        }
    }
    true
}

/// The register pairs to keep apart for by-address slots loaded for one
/// use in a body of several statements (codegen-patterns 12.4 R4(b)), as
/// `(slot value, earlier value)` for [`allocate_apart`], and the loads that
/// come after the body's first branch, call or label, which
/// [`check_late_slot_loads`] checks after allocation (as `(index of the
/// load in out, statement)`).
///
/// Such a slot is loaded where its statement needs it, into the lowest
/// address register that is free over its range *and* does not hold a
/// value an earlier statement left there, even when that value is dead:
///
/// - IIC_$RECEIVE 0xE70AC0..0xE70AD0: three slots, each read once, in
///   A0, A1 and A2 (callee-saved, so saved with `pea (A2)`) although A0
///   and A1 are dead by then;
/// - PROC2_$ALIGN_CTL 0xE41D82..0xE41D8E likewise (A0, A1, A2);
/// - XNS_IDP_$GET_STATS 0xE18FF4: the status slot in A1 after the stats
///   slot, held in A0 for three stores and dead (12.2);
/// - MMAP_$ALLOC_CONTIG 0xE0D902 A1 after A0; module-local 0xE32BB8 A2
///   after A0 and A1.
///
/// A register whose value was used up by `(An)+` / `-(An)` (a block copy)
/// does count as free: DIR_$ADD_MOUNT 0xE534DC loads its second slot
/// into A0 after the first one's `(A0)+` copy; ACL_ 0xE47944 into A2 after
/// a `(A2)+` copy, while the dead A0 of an earlier statement is passed
/// over.  Within one statement a dead register is reused (0xE41C2E
/// `movea.l (8,A6),A0` after A0's base was last read by the `lea` before).
///
/// Survey (ad-hoc script over the routines `tools/regalloc.py` analyses,
/// `movea.l (d,A6),An` loads of a slot): in the 105 such loads in
/// routines without branches and calls, this rule and plain lowest-free
/// (12.4 R1) agree 86 times; of the other 19 this rule picks the
/// original's register 17 times, lowest-free once (0xE41C2E, the same
/// statement), neither once (0xE3353A).  Before the first branch or call
/// of a routine that has some, the rule holds as without them (bead
/// domain-pascal-5aw.12; ad-hoc script over `tools/nestsurvey.py`'s
/// routines, not kept: of the slot loads in that straight-line prefix
/// whose register is dead after it, 496 of 553 fit this rule, the others
/// mostly argument lists, R4(a), or values held through a call, R4(c);
/// the value-parameter copies there, 133 of 135,
/// [`Selector::param_copies`]); DIR_$GET_ENTRYU 0xE4D51E `movea.l
/// (0x10,A6),A0` in its `if` condition, after the copy's `(A0)+`.  After
/// it, see [`check_late_slot_loads`].
fn fresh_slot_loads(
    out: &[Insn],
    fresh: &[(Reg, usize, Span)],
) -> (Vec<(Reg, Reg)>, LateSlotLoads, Vec<(Reg, Reg)>) {
    if fresh.is_empty() {
        return (Vec::new(), Vec::new(), Vec::new());
    }
    // The first instruction after which the straight-line rule is not
    // known: a branch, a call, or a label (a loop head, a join).
    let first_flow = out
        .iter()
        .position(|i| {
            matches!(
                i,
                Insn::Branch { .. }
                    | Insn::Dbf { .. }
                    | Insn::Jsr(_)
                    | Insn::Bsr { .. }
                    | Insn::Label(_)
                    | Insn::TableIndex { .. }
            )
        })
        .unwrap_or(out.len());
    // Registers used up by `(An)+` / `-(An)`.
    let consumed: Vec<u8> = out.iter().flat_map(autoinc_regs).collect();
    let mut apart = Vec::new();
    let mut late = Vec::new();
    let mut prefix = Vec::new();
    for &(v, start, span) in fresh {
        let load = out
            .iter()
            .position(|i| crate::regs::access(i).defs.contains(&v))
            .unwrap_or(out.len());
        if load > first_flow {
            // After the first branch or call: kept apart only from the
            // address values of earlier statements since a call that
            // reaches the load in straight-line code (the rule above,
            // restarted at the call; PROC2_$PGUID_TO_UPGID 0xE410B8
            // `movea.l (0x10,A6),A1` after `(0xc,A6)` in A0 and ML_$UNLOCK).
            let call = out[..load]
                .iter()
                .rposition(|i| {
                    matches!(
                        i,
                        Insn::Jsr(_)
                            | Insn::Bsr { .. }
                            | Insn::Label(_)
                            | Insn::Branch { .. }
                            | Insn::Dbf { .. }
                            | Insn::TableIndex { .. }
                            | Insn::TableJump { .. }
                    )
                })
                .filter(|&c| c < start && matches!(out[c], Insn::Jsr(_) | Insn::Bsr { .. }));
            if let Some(c) = call {
                for i in &out[c + 1..start] {
                    for d in crate::regs::access(i).defs {
                        if let Reg::A(n) = d {
                            if crate::regs::is_virtual(d) && !consumed.contains(&n) {
                                apart.push((v, d));
                            }
                        }
                    }
                }
            }
            late.push((load, call, span));
            continue;
        }
        for i in &out[..start] {
            for d in crate::regs::access(i).defs {
                if let Reg::A(n) = d {
                    if crate::regs::is_virtual(d) && !consumed.contains(&n) {
                        apart.push((v, d));
                        prefix.push((v, d));
                    }
                }
            }
        }
    }
    (apart, late, prefix)
}

/// The address registers an instruction steps with `(An)+` / `-(An)`
/// (the stack pointer excepted).
fn autoinc_regs(insn: &Insn) -> Vec<u8> {
    let eas: Vec<&Ea> = match insn {
        Insn::Move { src, dst, .. } => vec![src, dst],
        Insn::Clr { dst, .. } | Insn::Tst { dst, .. } => vec![dst],
        Insn::Cmp { src, .. } | Insn::Cmpa { src, .. } | Insn::Alu { src, .. } => vec![src],
        // `cmpm.l (Ay)+,(Ax)+` uses both up (0xE5AFF4, 0xE5B0C2, 0xE60EE4:
        // A1 last written by a `cmpm`, the element's `lea` into A1).
        Insn::Cmpm { src, dst, .. } => return vec![*src, *dst],
        _ => Vec::new(),
    };
    eas.into_iter()
        .filter_map(|ea| match ea {
            Ea::PostInc(a) | Ea::PreDec(a) if *a != SP => Some(*a),
            _ => None,
        })
        .collect()
}

/// The slot loads [`check_late_slot_loads`] checks: the index of each
/// load in the body, the call after which it follows in straight-line
/// code, if any, and its statement.
type LateSlotLoads = Vec<(usize, Option<usize>, Span)>;

/// The refusal of a slot load after the first branch or call whose
/// register the original's choice is not known for (12.4 R4(b)).
fn late_slot_refusal(span: Span) -> Diagnostic {
    unsupported(
        span,
        "in a body of several statements, a pointer parameter or by-address parameter used \
         once after a branch or a call, whose lowest free register an earlier statement left a \
         value in on some path (the original's choice there is not known, codegen-patterns \
         12.4 R4(b)), is",
    )
}

/// What reaches an address register at an instruction, on some path
/// ([`reaching_aregs`], [`reach_kinds`]): nothing wrote it on that path.
const REACH_ENTRY: u8 = 1;
/// A call wrote it.
const REACH_CALL: u8 = 2;
/// A block copy used it up (`(An)+` / `-(An)`).
const REACH_USED_UP: u8 = 4;
/// A parameter slot load `movea.l (d,A6),An`, d > 0.
const REACH_SLOT: u8 = 8;
/// Anything else.
const REACH_OTHER: u8 = 16;

/// Per instruction of an allocated body, before it: for A0..A4 the
/// instructions whose definition of the register reaches it on some path
/// (`usize::MAX` for the body's entry); `None` for unreachable code.
fn reaching_aregs(out: &[Insn]) -> Vec<Option<[BTreeSet<usize>; 5]>> {
    let succ = crate::regs::successors(out);
    let mut inn: Vec<Option<[BTreeSet<usize>; 5]>> = vec![None; out.len()];
    if !out.is_empty() {
        inn[0] = Some(std::array::from_fn(|_| BTreeSet::from([usize::MAX])));
    }
    loop {
        let mut changed = false;
        for i in 0..out.len() {
            let Some(mut st) = inn[i].clone() else {
                continue;
            };
            for d in crate::regs::access(&out[i]).defs {
                if let Reg::A(n) = d {
                    if n < 5 {
                        st[n as usize] = BTreeSet::from([i]);
                    }
                }
            }
            for s in succ[i].iter().flatten() {
                let merged = match &inn[*s] {
                    None => st.clone(),
                    Some(t) => std::array::from_fn(|n| t[n].union(&st[n]).copied().collect()),
                };
                if inn[*s].as_ref() != Some(&merged) {
                    inn[*s] = Some(merged);
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
    inn
}

/// Whether the late load at `k` may pass over dead slot loads
/// ([`pass_dead_slot_loads`]): a slot load whose slot no other
/// instruction of the body names, the shape the rule is verified on
/// (`tools/regalloc.py slotpass`, 41 of 41), or a copy `movea.l Dn,An`
/// ([`Selector::copy_to_a`]; review of bead domain-pascal-i24w, ad-hoc
/// script over the whole image: 9 copies after the first branch, call
/// or label in the rule's shape, 9 hits, 0xE09A94 A1 past A0, 0xE769AA
/// A3 past A0-A2).  A slot named elsewhere too (a parameter read from
/// the frame at each use, an escaped one in `dpc`) goes the other way
/// (same script, 35 loads of the rule's shape): past a dead load of the
/// same slot the image reuses its register 8 times of 8 (the AREA_
/// module-local 0xE08816 at 0xE0887C, 0xE08894, ... A0; VTOCE_$TRUNCATE
/// 0xE39E78, 0xE39E86 A0; IO_$ACQUIRE 0xE1A6AC A1), past dead loads of
/// other slots it takes the rule's register 22 times and reuses the
/// lowest 5 (VTOCE_$TRUNCATE 0xE39E90, XPD_$PUT_REGISTERS 0xE5C3B6,
/// FILE_$READ_LOCK_ENTRYI 0xE60BC0 A0); such a load is not passed over
/// and stays refused.
fn passes_dead_slot_loads(out: &[Insn], k: usize) -> bool {
    match out.get(k) {
        Some(Insn::Movea {
            src: Ea::Reg(Reg::D(_)),
            ..
        }) => true,
        Some(Insn::Movea {
            src: src @ Ea::Disp(d, FP),
            ..
        }) if *d > 0 => {
            let slot = src.to_string();
            !out.iter()
                .enumerate()
                .any(|(i, x)| i != k && x.to_string().contains(&slot))
        }
        _ => false,
    }
}

/// The refusal of an element address read once whose `lea` should go to
/// A1 and that colouring does not put there ([`once_elem_lea`]).
const ONCE_LEA_NOT_A1: &str = "an element address of another unit's array or through a pointer \
     loaded from memory, read once, that the image puts in A1 (its base in A0, A1 free and \
     clean, codegen-patterns 5.2) where the colouring cannot (bead domain-pascal-1ibr) is";

/// How `insn` writes back the memory operand it reaches through An:
/// `Some(true)` for `addq`/`subq` (the image's three read-modify-write
/// sites with the base in A0: ACL_$UP 0xE47058 `addq.w`, 0xE41F5A and
/// 0xE42044 `subq.w`), `Some(false)` for any other operation that reads
/// and writes it (`bset`, `bclr`, `or.b Dn,(d,An)`, ...: none with the
/// base in A0), `None` when it does not write it back.
fn writes_back_through(insn: &Insn, n: u8) -> Option<bool> {
    let through = |ea: &Ea| {
        matches!(ea, Ea::Ind(a) | Ea::Disp(_, a) | Ea::Idx(_, a, _, _)
            | Ea::PostInc(a) | Ea::PreDec(a) if *a == n)
    };
    match insn {
        Insn::Addq { dst, .. } | Insn::Subq { dst, .. } => through(dst).then_some(true),
        Insn::AluImm { dst, .. }
        | Insn::Unary { dst, .. }
        | Insn::BitImm { dst, .. }
        | Insn::Bit { dst, .. }
        | Insn::AluToMem { dst, .. } => through(dst).then_some(false),
        _ => None,
    }
}

/// After allocation: the register of an element address of another
/// unit's array or through a pointer loaded from memory, formed by `lea
/// (d,An,Dx),Am` at `k` and read once in no call's range
/// ([`select_body_with`], `elem_leas`; codegen-patterns 5.2, "The
/// element's address as a value"; `tools/regalloc.py elemonce`, bead
/// domain-pascal-1ibr).  `Ok(None)` when the colouring gives the image's
/// register, `Ok(Some(pair))` for the address and its base to keep apart
/// in a new colouring (the address then takes A1), `Err` when the shape
/// is not settled.
///
/// Survey (`elemonce`, the image's 81 such `lea`s read by the next
/// instruction, the base read by the `lea` alone and set by a `movea.l`
/// for it, no other indexed `lea` before or after, no push between, the
/// base in A0): with A1 free over the address's range and clean on every
/// path (no instruction wrote it, or a call or `(A1)+` last did), the
/// address goes to A1, 56 of 57 (the module-local routine at 0xE1C204,
/// 0xE1C242 `lea (0,A0,D0.w),A1; move.l A1,(-80,A6)`; ACL_$IN_SUBSYS 0xE470B2
/// `lea (0,A0,D0.w),A1; tst.w (-15706,A1)`; PROC2_$COMPLETE_FORK 0xE7360C;
/// against it XPD_$PUT_REGISTERS 0xE5C394 `lea (0,A0,D0.l),A0; move.l
/// (-30,A0),D5`, not explained); with A1 live over the range (3:
/// MMAP_ 0xE0D2E8 `lea (0,A0,D7.l),A0; move.w D2,(-8182,A0)`) or dirty
/// on every path (6: 0xE32CD6 `lea (78,A0,D3.l),A0`, A1 holding a dead
/// `lea`; 0xE4718E), into A0 itself, 9 of 9; a read that writes the
/// element back (3: ACL_$UP 0xE47058 `lea (0,A0,D0.w),A0; addq.w
/// #1,(-15706,A0)`, A1 clean), into A0 itself, 3 of 3.  Refused: A1 dirty
/// on some paths only (6 into A1, 6 into A0), a base in another register
/// (in A1: 13 into A1 itself and 2 others with A0 live, 21 and 10 with A0
/// dirty, 11 into A0 and 8 others with A0 clean), and the other shapes.
fn once_elem_lea(
    pre: &[Insn],
    out: &[Insn],
    k: usize,
    exit: &[Reg],
    holds: &[(usize, Reg)],
) -> Result<Option<(Reg, Reg)>, &'static str> {
    const BASE: &str = "an element address of another unit's array or through a pointer \
         loaded from memory, read once in no call's range, from a base other than A0 (the \
         `lea` into the base's register or another: in A1, 13 against 2 with A0 live, 21 \
         against 10 with A0 dirty, 11 into A0 and 8 others with A0 clean; not settled, \
         codegen-patterns 5.2; bead domain-pascal-1ibr) is";
    const MIXED: &str = "an element address of another unit's array or through a pointer \
         loaded from memory, read once in no call's range, from a base in A0 while A1 holds \
         an earlier value on some paths only (the `lea` into A1 6 times, into A0 6 times: not \
         settled, codegen-patterns 5.2; bead domain-pascal-1ibr) is";
    let (
        Some(Insn::Lea {
            src: Ea::Idx(_, b, _, _),
            dst,
        }),
        Some(Insn::Lea {
            src: Ea::Idx(_, vb, _, _),
            dst: vd,
        }),
    ) = (out.get(k), pre.get(k))
    else {
        return Err(ONCE_LEA_SHAPE);
    };
    let (vb, vd) = (Reg::A(*vb), Reg::A(*vd));
    once_elem_shape(pre, k)?;
    if *b != 0 {
        return Err(BASE);
    }
    const WRITE_BACK: &str = "an element of another unit's array or through a pointer \
         loaded from memory, from a base in A0, written back through its `lea` by an \
         operation other than `addq`/`subq` (`bset`, `bclr`, `or.b`: no site with the base in \
         A0, codegen-patterns 5.2; bead domain-pascal-1ibr) is";
    let own = if let Some(addq) = writes_back_through(&out[k + 1], *dst) {
        if !addq {
            return Err(WRITE_BACK);
        }
        true
    } else {
        let a1 = crate::regs::RegKey(Reg::A(1));
        let live = crate::regs::liveness(out, exit, holds);
        let busy = *dst != 1 && live[k].contains(&a1);
        let reach = reaching_aregs(out);
        let kinds = match reach.get(k) {
            Some(Some(r)) => reach_kinds(out, 1, &r[1]),
            _ => return Err(ONCE_LEA_SHAPE),
        };
        let clean = REACH_ENTRY | REACH_CALL | REACH_USED_UP;
        if busy || kinds & clean == 0 {
            true
        } else if kinds & !clean == 0 {
            false
        } else {
            return Err(MIXED);
        }
    };
    match (own, *dst) {
        (true, 0) | (false, 1) => Ok(None),
        (false, _) => Ok(Some((vd, vb))),
        (true, _) => Err(ONCE_LEA_SHAPE),
    }
}

/// What a block's two addresses are formed for
/// ([`Selector::block_addresses`]).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum BlockUse {
    /// A record comparison (`cmpm`, with its count's `moveq`).
    Compare,
    /// A copy of up to 18 bytes, unrolled, no count.
    Unrolled,
    /// A longword `dbf` copy, with its count's `moveq`.
    Loop,
    /// An array of char copied by bytes.
    Chars,
}

/// Whether `i`, one of an element's index instructions, reads registers
/// and immediates only ([`Selector::block_addresses`]: an element first).
fn index_reads_registers(i: &Insn) -> bool {
    let plain = |e: &Ea| matches!(e, Ea::Reg(_) | Ea::Imm(_));
    match i {
        Insn::Moveq { .. } | Insn::Ext { .. } | Insn::Shift { .. } => true,
        Insn::Move { src, dst, .. } => plain(src) && matches!(dst, Ea::Reg(_)),
        Insn::Alu { src, .. } | Insn::Mul { src, .. } => plain(src),
        _ => false,
    }
}

/// Whether `i`, one of an element's index instructions, zero-extends a
/// byte (`clr.w Dn` / `move.b x,Dn`; codegen-patterns 5.2, "Byte
/// indices").
fn zero_extends_byte(i: &Insn) -> bool {
    matches!(i, Insn::Clr { .. } | Insn::Move { size: Size::B, .. })
}

/// Whether `i`, one of an element's index instructions, zero-extends a
/// byte (`clr.w Dn; move.b x,Dn`), not a word (`clr.l Dn; move.w x,Dn`,
/// SMD_ 0xE6E4F4 for an 8-byte copy's source; [`Selector::copy8_element`]).
fn widens_byte(i: &Insn) -> bool {
    matches!(
        i,
        Insn::Clr {
            size: Size::B | Size::W,
            ..
        } | Insn::Move { size: Size::B, .. }
    )
}

/// The refusal of a block copy or comparison whose two blocks are both
/// array elements indexed at run time ([`Selector::block_addresses`]).
const ELEMENT_BOTH: &str = "a block copy or comparison of two array elements indexed at run \
     time (both indices, then both `lea`s, in orders and registers not modelled: NAME_$FORK \
     0xE73E90..0xE73EA0, PCHIST_$UNIX_PROFIL_FORK 0xE5CC6C..0xE5CC8A, ACL_$ALLOC_ASID \
     0xE73C22..0xE73C48; codegen-patterns 5.2, \"Block addresses\"; bead domain-pascal-dsr5) is";

/// The refusal of a block that is an element of another unit's array or
